//! Public profile observation only. Analysis, seed, output access, correctness,
//! encoding, and file writes stay outside the profile timing groups.
use pine_runtime::{
    Bar, HistoricalRuntime, PineValue, RuntimeResult, public_runtime_profiled_result_json,
};
use pine_sema::analyze_source;
use pine_syntax::{Severity, SourceFile};
use serde_json::{Value, json};
use std::hint::black_box;
use std::time::Instant;

const GROUPS: usize = 31;
const CALLS_PER_GROUP: usize = 256;
const WARMUP_CALLS: usize = 64;

fn quarter_ticks(index: usize) -> u64 {
    400 + (index % 17) as u64
}

fn bar(index: usize) -> Bar {
    let close = quarter_ticks(index) as f64 / 4.0;
    Bar {
        time: 1_700_000_000 + index as i64 * 60,
        open: close,
        high: close + 1.0,
        low: close - 1.0,
        close,
        volume: 100.0,
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().collect();
    if args.len() != 6 {
        return Err("usage: capacity_probe source.pine kind bars window output.json".into());
    }
    let kind = args[2].as_str();
    let bars: usize = args[3].parse()?;
    let window: usize = args[4].parse()?;
    match kind {
        "sma" if [14, 129, 5000, 100_000, 1_000_000].contains(&window) && bars == window + 1000 => {
        }
        "empty" if window == 0 && bars == 0 => {}
        "constant" | "close" | "multiClose" if window == 0 && bars == 1_000_000 => {}
        _ => return Err("unexpected fixture parameters".into()),
    }
    let source = SourceFile::new("capacity_probe.pine", std::fs::read_to_string(&args[1])?);
    let analyze_started = Instant::now();
    let analysis = analyze_source(&source);
    let analyze_ms = analyze_started.elapsed().as_secs_f64() * 1000.0;
    if analysis
        .diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == Severity::Error)
    {
        return Err(format!("{:?}", analysis.diagnostics).into());
    }
    let hir = analysis.hir.ok_or("no HIR")?;
    let mut runtime = HistoricalRuntime::new(&hir);
    let seed_started = Instant::now();
    for index in 0..bars {
        runtime
            .append_bar(bar(index))
            .map_err(|error| error.message)?;
    }
    let seed_ms = seed_started.elapsed().as_secs_f64() * 1000.0;

    // Direct fixture formulas share no state, history tree, checkpoint, or
    // capacity code with the interpreter. SMA sums integer quarter ticks first.
    let integer_sum =
        (kind == "sma").then(|| (bars - window..bars).map(quarter_ticks).sum::<u64>());
    let close = if bars == 0 {
        0.0
    } else {
        quarter_ticks(bars - 1) as f64 / 4.0
    };
    let expected = match kind {
        "sma" => vec![(integer_sum.unwrap() as f64 / 4.0) / window as f64],
        "empty" => vec![],
        "constant" => vec![71.25],
        "close" => vec![close],
        "multiClose" => vec![close, close * 2.0, close + 1.0, -close],
        _ => unreachable!(),
    };
    let result_started = Instant::now();
    let result = runtime.result_view();
    if result.plots.len() != expected.len() {
        return Err("unexpected plot count".into());
    }
    let mut plot_values = Vec::new();
    let mut plot_tail_bits = Vec::new();
    for (plot, expected_value) in result.plots.iter().zip(&expected) {
        if plot.values.len() != bars {
            return Err("unexpected plot history length".into());
        }
        let last = match plot.values.iter().last() {
            Some(PineValue::Float(value)) => *value,
            Some(PineValue::Int(value)) => *value as f64,
            _ => return Err("final plot value is missing or nonnumeric".into()),
        };
        if last.to_bits() != expected_value.to_bits() {
            return Err(format!(
                "plot tail bits differ: {:016x} != {:016x}",
                last.to_bits(),
                expected_value.to_bits()
            )
            .into());
        }
        plot_values.push(plot.values.len());
        plot_tail_bits.push(format!("{:016x}", last.to_bits()));
    }
    drop(result);
    let result_ms = result_started.elapsed().as_secs_f64() * 1000.0;

    let expected_profile = runtime.profile();
    if expected_profile.bars != bars {
        return Err("profile bar count mismatch".into());
    }
    for _ in 0..WARMUP_CALLS {
        black_box(black_box(&runtime).profile());
    }
    let mut groups_ms = [0.0; GROUPS];
    for elapsed in &mut groups_ms {
        let started = Instant::now();
        for _ in 0..CALLS_PER_GROUP {
            black_box(black_box(&runtime).profile());
        }
        *elapsed = started.elapsed().as_secs_f64() * 1000.0;
    }
    if runtime.profile() != expected_profile {
        return Err("profile observation changed runtime counters".into());
    }
    let mut sorted = groups_ms;
    sorted.sort_by(f64::total_cmp);
    let median_per_call_ns = sorted[GROUPS / 2] * 1_000_000.0 / CALLS_PER_GROUP as f64;

    // Public encoder retains every public profile field without encoding the
    // large history. This encoding is outside the profile timing interval.
    let profile_document =
        public_runtime_profiled_result_json(&RuntimeResult::default(), &expected_profile);
    let mut profile_document: Value = serde_json::from_str(&profile_document)?;
    let profile_json = profile_document["profile"].take();
    let profile_field_count = profile_json
        .as_object()
        .ok_or("public encoder omitted profile object")?
        .len();
    let receipt = json!({
        "probe": "publicProfileAppendCapacity", "source": args[1], "kind": kind,
        "window": window, "bars": bars, "groups": GROUPS,
        "callsPerGroup": CALLS_PER_GROUP, "timedCalls": GROUPS * CALLS_PER_GROUP,
        "warmupCalls": WARMUP_CALLS, "groupMs": groups_ms,
        "profileMedianPerCallNs": median_per_call_ns,
        "analyzeMs": analyze_ms, "seedMs": seed_ms, "resultObservationMs": result_ms,
        "measurementScope": "31 groups of 256 public HistoricalRuntime::profile calls; full profile and runtime reference are black-boxed",
        "profileScope": "all fields emitted by public_runtime_profiled_result_json",
        "profileFieldCount": profile_field_count, "profile": profile_json,
        "profileUnchanged": true, "plotValues": plot_values, "plotTailBits": plot_tail_bits,
        "oracleTailBits": expected.iter().map(|v| format!("{:016x}", v.to_bits())).collect::<Vec<_>>(),
        "oracleIntegerQuarterTicks": integer_sum,
        "oracleWindowStart": (kind == "sma").then(|| bars - window),
        "oracleWindowEndExclusive": (kind == "sma").then_some(bars),
        "oracle": "direct integer quarter-tick sum for SMA; direct constant or final-close formulas for other plots; empty fixture has no bars or plots",
    });
    let encoded = serde_json::to_string(&receipt)?;
    std::fs::write(&args[5], &encoded)?;
    println!("{encoded}");
    Ok(())
}

