//! Standalone public API attribution; linking and fresh-process scheduling belong
//! to the coordinator. Correctness, output encoding, profiling, and disposal are
//! outside each timed call. No borrowed/private state or synthetic deltas.
use pine_runtime::*;
use pine_sema::analyze_source;
use pine_syntax::{Severity, SourceFile};
use serde_json::{Value, json};
use std::alloc::{GlobalAlloc, Layout, System};
use std::hint::black_box;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
use std::time::Instant;

const SAMPLES: usize = 9;
const LIMIT: usize = 1_000_000;
struct CountingAllocator;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static PEAK: AtomicUsize = AtomicUsize::new(0);
static ALLOCATED: AtomicUsize = AtomicUsize::new(0);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
fn allocation(size: usize) {
    ALLOCATED.fetch_add(size, Relaxed);
    ALLOCS.fetch_add(1, Relaxed);
    let live = LIVE.fetch_add(size, Relaxed) + size;
    PEAK.fetch_max(live, Relaxed);
}
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let p = unsafe { System.alloc(layout) };
        if !p.is_null() {
            allocation(layout.size());
        }
        p
    }
    unsafe fn dealloc(&self, p: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Relaxed);
        unsafe { System.dealloc(p, layout) }
    }
    unsafe fn realloc(&self, p: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let q = unsafe { System.realloc(p, layout, size) };
        if !q.is_null() {
            LIVE.fetch_sub(layout.size(), Relaxed);
            allocation(size);
        }
        q
    }
}
#[global_allocator]
static GLOBAL: CountingAllocator = CountingAllocator;
#[derive(Clone, Copy)]
struct Stage {
    ms: f64,
    bytes: usize,
    count: usize,
    peak: usize,
    live_delta: i64,
}
fn measure<T>(f: impl FnOnce() -> T) -> (T, Stage) {
    let initial = LIVE.load(Relaxed);
    PEAK.store(initial, Relaxed);
    let bytes = ALLOCATED.load(Relaxed);
    let count = ALLOCS.load(Relaxed);
    let started = Instant::now();
    let result = black_box(f());
    let ms = started.elapsed().as_secs_f64() * 1000.0;
    (
        result,
        Stage {
            ms,
            bytes: ALLOCATED.load(Relaxed) - bytes,
            count: ALLOCS.load(Relaxed) - count,
            peak: PEAK.load(Relaxed).saturating_sub(initial),
            live_delta: LIVE.load(Relaxed) as i64 - initial as i64,
        },
    )
}
fn stage_json(s: Stage) -> Value {
    json!({"ms": s.ms, "allocatedBytes": s.bytes, "allocations": s.count,
        "peakAdditionalLiveBytes": s.peak, "liveDeltaBytes": s.live_delta})
}
fn close(index: usize) -> f64 {
    100.0 + index as f64 / 4.0
}
fn bar(index: usize, price: f64) -> Bar {
    Bar {
        time: 1_700_000_000 + index as i64 * 60,
        open: price,
        high: price + 1.0,
        low: price - 1.0,
        close: price,
        volume: 100.0,
    }
}
fn script(case: &str) -> Result<&'static str, String> {
    Ok(match case {
        "none" => "//@version=6\nindicator(\"valuewhen none\")\nplot(close)\n",
        "dynamic" => {
            "//@version=6\nindicator(\"valuewhen dynamic\")\nplot(ta.valuewhen(true, close, bar_index % 5000))\n"
        }
        "strategy" => {
            "//@version=6\nstrategy(\"valuewhen strategy checkpoint\", calc_on_order_fills=true, calc_on_every_tick=true)\nplot(ta.valuewhen(true, close, bar_index % 5000))\n"
        }
        "sparse" => {
            "//@version=6\nindicator(\"valuewhen sparse\")\nplot(ta.valuewhen(bar_index % 257 == 0, close, bar_index % 17))\n"
        }
        "fixed0" => {
            "//@version=6\nindicator(\"valuewhen fixed0\")\nplot(ta.valuewhen(true, close, 0))\n"
        }
        "fixed1" => {
            "//@version=6\nindicator(\"valuewhen fixed1\")\nplot(ta.valuewhen(true, close, 1))\n"
        }
        _ => return Err("case must be none, dynamic, strategy, sparse, fixed0, or fixed1".into()),
    })
}
// Direct index arithmetic is independent of the interpreter's event storage.
// Source values are exact integer quarter ticks throughout the allowed range.
fn oracle(case: &str, index: usize, replacement: Option<(usize, f64)>) -> Option<f64> {
    let event_index = match case {
        "none" | "fixed0" => Some(index),
        "fixed1" => index.checked_sub(1),
        "dynamic" | "strategy" => index.checked_sub(index % 5000),
        "sparse" => (index / 257)
            .checked_sub(index % 17)
            .map(|event| event * 257),
        _ => unreachable!(),
    }?;
    Some(match replacement {
        Some((at, price)) if event_index == at => price,
        _ => close(event_index),
    })
}
fn retained_events(case: &str, bars: usize) -> usize {
    match case {
        "none" => 0,
        "fixed0" => bars.min(1),
        "fixed1" => bars.min(2),
        "dynamic" | "strategy" => bars.min(LIMIT),
        "sparse" => {
            if bars == 0 {
                0
            } else {
                ((bars - 1) / 257 + 1).min(LIMIT)
            }
        }
        _ => unreachable!(),
    }
}
fn verify_value(actual: &PineValue, expected: Option<f64>) -> Result<u64, String> {
    match (actual, expected) {
        (PineValue::Na, None) => Ok(u64::MAX),
        (PineValue::Float(value), Some(expected)) if value.to_bits() == expected.to_bits() => {
            Ok(value.to_bits())
        }
        _ => Err(format!(
            "direct oracle mismatch: actual={actual:?}, expected={expected:?}"
        )),
    }
}
fn check_tail(
    view: RuntimeResultView<'_>,
    case: &str,
    bars: usize,
    replacement: Option<(usize, f64)>,
) -> Result<u64, String> {
    if view.plots.len() != 1 || view.plots[0].values.len() != bars {
        return Err("fixture must expose one complete plot history".into());
    }
    let last = view.plots[0].values.iter().last().ok_or("empty plot")?;
    verify_value(last, oracle(case, bars - 1, replacement))
}
fn check_all(
    view: RuntimeResultView<'_>,
    case: &str,
    bars: usize,
    replacement: Option<(usize, f64)>,
) -> Result<Value, String> {
    if view.plots.len() != 1 || view.plots[0].values.len() != bars {
        return Err("fixture must expose one complete plot history".into());
    }
    let mut hash = 0xcbf29ce484222325_u64;
    let mut na = 0_usize;
    for (index, value) in view.plots[0].values.iter().enumerate() {
        let expected = oracle(case, index, replacement);
        na += usize::from(expected.is_none());
        let bits = verify_value(value, expected)?;
        for byte in bits.to_le_bytes() {
            hash = (hash ^ u64::from(byte)).wrapping_mul(0x100000001b3);
        }
    }
    Ok(json!({"plotValues": bars, "naValues": na,
        "allValuesMatchDirectOracle": true, "fnv1a64ValueBitsLe": format!("{hash:016x}")}))
}
fn profile_json(profile: &RuntimeProfile) -> Result<Value, Box<dyn std::error::Error>> {
    let encoded = public_runtime_profiled_result_json(&RuntimeResult::default(), profile);
    let mut value: Value = serde_json::from_str(&encoded)?;
    Ok(value["profile"].take())
}
fn check_profile(profile: &RuntimeProfile, case: &str, bars: usize) -> Result<(), String> {
    if profile.bars != bars
        || profile.valuewhen_state_values != retained_events(case, bars)
        || profile.valuewhen_state_slots != usize::from(case != "none")
    {
        return Err(format!("bar/event/callsite counters diverged: {profile:?}"));
    }
    Ok(())
}
fn payload_path(receipt: &Path, suffix: &str) -> PathBuf {
    receipt.with_extension(format!("{suffix}.json"))
}
fn save_snapshot(
    receipt: &Path,
    suffix: &str,
    view: &RuntimeResultView<'_>,
) -> Result<String, Box<dyn std::error::Error>> {
    let path = payload_path(receipt, suffix);
    std::fs::write(&path, public_runtime_result_view_json(view))?;
    Ok(path.to_string_lossy().into_owned())
}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().collect();
    if args.len() != 4 {
        return Err("usage: valuewhen_probe CASE BARS RECEIPT.json".into());
    }
    let case = &args[1];
    let source_text = script(case)?;
    let count: usize = args[2].parse()?;
    if !(129..=200_123).contains(&count) {
        return Err("BARS must be 129..200123; qualification uses 100123".into());
    }
    let receipt_path = Path::new(&args[3]);
    let source = SourceFile::new("valuewhen_probe.pine", source_text);
    let (analysis, analyze) = measure(|| analyze_source(&source));
    if analysis
        .diagnostics
        .iter()
        .any(|d| d.severity == Severity::Error)
    {
        return Err(format!("{:?}", analysis.diagnostics).into());
    }
    let hir = analysis.hir.ok_or("missing HIR")?;
    let bars: Vec<_> = (0..count).map(|index| bar(index, close(index))).collect();
    let mut history = HistoricalRuntime::new(&hir);
    let (seed, seed_metric) = measure(|| history.append_bars(&bars));
    seed.map_err(|error| error.message)?;
    let history_profile = history.profile();
    check_profile(&history_profile, case, count)?;
    if case == "strategy"
        && (history_profile.strategy_script_passes != count
            || history_profile.strategy_recalculation_passes != 0)
    {
        return Err(
            "no-fill checkpoint fixture must execute once per seeded historical bar".into(),
        );
    }
    let seed_oracle = check_all(history.result_view(), case, count, None)?;
    let mut raw_files = vec![save_snapshot(receipt_path, "seed", &history.result_view())?];
    let mut clone_samples = Vec::with_capacity(SAMPLES);
    let mut append_samples = Vec::with_capacity(SAMPLES);
    for sample in 0..SAMPLES {
        let (mut checkpoint, clone_metric) = measure(|| black_box(&history).clone());
        check_tail(checkpoint.result_view(), case, count, None)?;
        let replacement = close(count) + sample as f64 / 8.0;
        let (append, append_metric) = measure(|| checkpoint.append_bar(bar(count, replacement)));
        append.map_err(|error| error.message)?;
        check_tail(
            checkpoint.result_view(),
            case,
            count + 1,
            Some((count, replacement)),
        )?;
        check_profile(&checkpoint.profile(), case, count + 1)?;
        // Disposal stays outside both construction and first-write measurements.
        drop(checkpoint);
        clone_samples.push(stage_json(clone_metric));
        append_samples.push(stage_json(append_metric));
    }
    check_all(history.result_view(), case, count, None)?;
    if history.profile() != history_profile {
        return Err("checkpoint mutation touched original profile".into());
    }
    drop(history);
    let mut realtime = RealtimeRuntime::new(&hir);
    let (seed, realtime_seed_metric) = measure(|| realtime.seed_historical_without_output(&bars));
    seed.map_err(|error| error.message)?;
    check_all(realtime.result_view(), case, count, None)?;
    let seeded_revision = realtime.revision();
    let mut without_samples = Vec::with_capacity(SAMPLES);
    let mut apply_samples = Vec::with_capacity(SAMPLES);
    let mut forming_checks = Vec::with_capacity(SAMPLES * 2);
    for sample in 0..SAMPLES {
        let replacement = close(count) + (sample + 1) as f64 / 8.0;
        let (updated, metric) =
            measure(|| realtime.update_without_output(BarUpdate::forming(bar(count, replacement))));
        updated.map_err(|error| error.message)?;
        let tail_bits = check_tail(
            realtime.result_view(),
            case,
            count + 1,
            Some((count, replacement)),
        )?;
        check_profile(&realtime.profile(), case, count + 1)?;
        check_profile(&realtime.confirmed_profile(), case, count)?;
        if realtime.last_changes().is_some() {
            return Err("without-output update retained changes".into());
        }
        forming_checks.push(json!({"method": "update_without_output", "sample": sample,
            "oracleBits": format!("{tail_bits:016x}"), "previewEvents": retained_events(case, count+1),
            "confirmedEvents": retained_events(case,count), "revision": realtime.revision()}));
        without_samples.push(stage_json(metric));
    }
    for sample in 0..SAMPLES {
        let replacement = close(count) - (sample + 1) as f64 / 8.0;
        let (changes, metric) =
            measure(|| realtime.apply_update(BarUpdate::forming(bar(count, replacement))));
        let changes = changes.map_err(|error| error.message)?;
        let tail_bits = check_tail(
            realtime.result_view(),
            case,
            count + 1,
            Some((count, replacement)),
        )?;
        check_profile(&realtime.profile(), case, count + 1)?;
        check_profile(&realtime.confirmed_profile(), case, count)?;
        if realtime.last_changes() != Some(&changes) {
            return Err("public last_changes diverged from returned delta".into());
        }
        let path = payload_path(receipt_path, &format!("forming-apply-{sample}"));
        std::fs::write(&path, public_runtime_changes_json(&changes))?;
        raw_files.push(path.to_string_lossy().into_owned());
        forming_checks.push(json!({"method": "apply_update", "sample": sample,
            "oracleBits": format!("{tail_bits:016x}"), "previewEvents": retained_events(case,count+1),
            "confirmedEvents": retained_events(case,count), "revision": realtime.revision()}));
        drop(changes);
        apply_samples.push(stage_json(metric));
    }
    let final_close = close(count) + 0.375;
    let (confirmed, confirm_metric) =
        measure(|| realtime.update_without_output(BarUpdate::confirmed(bar(count, final_close))));
    confirmed.map_err(|error| error.message)?;
    check_profile(&realtime.profile(), case, count + 1)?;
    check_profile(&realtime.confirmed_profile(), case, count + 1)?;
    let confirmed_oracle = check_all(
        realtime.result_view(),
        case,
        count + 1,
        Some((count, final_close)),
    )?;
    let confirmed_profile = profile_json(&realtime.profile())?;
    raw_files.push(save_snapshot(
        receipt_path,
        "confirmed",
        &realtime.result_view(),
    )?);
    // The next historical append must see exactly one committed value from the
    // preceding open bar, regardless of its eighteen speculative replacements.
    let (historical, historical_metric) = measure(|| {
        realtime.update_without_output(BarUpdate::historical(bar(count + 1, close(count + 1))))
    });
    historical.map_err(|error| error.message)?;
    check_profile(&realtime.profile(), case, count + 2)?;
    let final_oracle = check_all(
        realtime.result_view(),
        case,
        count + 2,
        Some((count, final_close)),
    )?;
    let final_profile = profile_json(&realtime.profile())?;
    raw_files.push(save_snapshot(
        receipt_path,
        "next-historical",
        &realtime.result_view(),
    )?);
    if realtime.revision() != seeded_revision + (2 * SAMPLES + 2) as u64 {
        return Err("unexpected public revision sequence".into());
    }
    let receipt = json!({
        "probe": "publicValuewhenPersistentHistory", "case": case, "bars": count,
        "pineSource": source_text, "samplesPerRepeatedStage": SAMPLES,
        "stages": {"analyze": stage_json(analyze), "historicalSeed": stage_json(seed_metric),
            "historicalClone": clone_samples, "historicalAppendSharedClone": append_samples,
            "realtimeSeedWithoutOutput": stage_json(realtime_seed_metric),
            "formingWithoutOutput": without_samples, "formingApplyUpdate": apply_samples,
            "confirmedWithoutOutput": stage_json(confirm_metric), "nextHistoricalWithoutOutput": stage_json(historical_metric)},
        "seedProfile": profile_json(&history_profile)?, "confirmedProfile": confirmed_profile,
        "finalProfile": final_profile, "formingChecks": forming_checks,
        "seedOracle": seed_oracle, "confirmedOracle": confirmed_oracle, "finalOracle": final_oracle,
        "seededRevision": seeded_revision, "publicRevision": realtime.revision(), "rawPayloadFiles": raw_files,
        "allowedBeforeAfterProfileDifferences": ["valuewhenStateValueCapacity"],
        "oracle": "exact quarter-tick input; direct event-index arithmetic, Float IEEE bits, Na sentinel; each full seed/confirmed/next-historical plot checked",
        "measurementScope": "each call ends before returned runtime/delta disposal; allocation counters include all runtime work inside the named public call; profiling, correctness, encoders and file writes stay outside",
        "strategyTrigger": if case == "strategy" { "calc_on_order_fills=true creates/restores a checkpoint per historical script bar; no orders or fills in this fixture" } else { "not a strategy" },
        "limitations": "public whole-runtime clone includes all state; no isolated valuewhen-only attribution or process RSS; fixed and no-valuewhen controls identify constant API overhead; ordinary numeric Pine sources only; strategy case qualifies no-fill checkpoint costs, not actual fill-recalculation performance",
    });
    let encoded = serde_json::to_string(&receipt)?;
    std::fs::write(receipt_path, &encoded)?;
    println!("{encoded}");
    Ok(())
}

capacity_runner.py.content:
"""Prepare or measure public profile observations; never build or link.

9 fixed cases, 3 fresh processes per version, alternating paired order.
Canonical gates, frozen source, release and both exact links must already exist.
"""
from __future__ import annotations
import argparse
from datetime import datetime, timezone
import math
import os
from pathlib import Path
import re
import statistics
import struct
import subprocess

from evidence_common import D, ROOT, directory, execute, loads, read, save, sha, source

WINDOWS = (14, 129, 5000, 100_000, 1_000_000)
GROUPS, CALLS, WARMUP, REPETITIONS = 31, 256, 64, 3
TIMINGS = ("profileMedianPerCallNs", "analyzeMs", "seedMs", "resultObservationMs")
TOP = {
    "probe", "source", "kind", "window", "bars", "groups", "callsPerGroup",
    "timedCalls", "warmupCalls", "groupMs", *TIMINGS, "measurementScope",
    "profileScope", "profileFieldCount", "profile", "profileUnchanged",
    "plotValues", "plotTailBits", "oracleTailBits", "oracleIntegerQuarterTicks",
    "oracleWindowStart", "oracleWindowEndExclusive", "oracle",
}
PROFILE_SOURCE = ROOT / "crates/pine-runtime/src/output/json/profile.rs"
PHASE_NAMES = ("gate-windows", "gate-linux", "release", "link-capacity-after")


def integer(value):
    if type(value) is not int:
        raise ValueError("Expected integer")
    return value


def numeric(value, positive=False):
    if (isinstance(value, bool) or not isinstance(value, (int, float))
            or not math.isfinite(value) or value < 0 or (positive and value == 0)):
        raise ValueError("Expected finite nonnegative timing")
    return value


def profile_fields():
    fields = re.findall(r'\\"([A-Za-z][A-Za-z0-9]*)\\":',
                        PROFILE_SOURCE.read_text(encoding="utf8"))
    if len(fields) < 100 or len(fields) != len(set(fields)):
        raise ValueError("Unexpected public profile schema")
    return sorted(fields)


def prepare():
    cases = [{"name": f"sma{window}", "kind": "sma", "window": window,
              "bars": window + 1000, "plots": 1,
              "body": f"plot(ta.sma(close, {window}))\n"} for window in WINDOWS]
    cases.extend([
        {"name": "empty", "kind": "empty", "window": 0, "bars": 0, "plots": 0,
         "body": ""},
        {"name": "constant1m", "kind": "constant", "window": 0,
         "bars": 1_000_000, "plots": 1, "body": "plot(71.25)\n"},
        {"name": "close1m", "kind": "close", "window": 0,
         "bars": 1_000_000, "plots": 1, "body": "plot(close)\n"},
        {"name": "multiClose1m", "kind": "multiClose", "window": 0,
         "bars": 1_000_000, "plots": 4,
         "body": "plot(close)\nplot(close * 2.0)\nplot(close + 1.0)\nplot(-close)\n"},
    ])
    for case in cases:
        text = '//@version=6\nindicator("append capacity profile")\n' + case.pop("body")
        case["source"] = source(D / ("capacity-" + case["name"] + ".pine"), text)
    plan = {
        "cases": cases, "repetitionsPerVersion": REPETITIONS,
        "plannedProcesses": len(cases) * REPETITIONS * 2,
        "groupsPerProcess": GROUPS, "callsPerGroup": CALLS,
        "timedCallsPerProcess": GROUPS * CALLS, "timingFields": list(TIMINGS),
        "profileSchema": {"path": str(PROFILE_SOURCE), "sha256": sha(PROFILE_SOURCE),
                          "fields": profile_fields()},
        "probeSource": {"path": str(D / "capacity_probe.rs"),
                        "sha256": sha(D / "capacity_probe.rs")},
        "scope": "Complete public HistoricalRuntime::profile calls; analysis, seed and result-observation controls are not whole-runtime or RSS qualification",
        "fixture": "close=(400+index%17)/4; SMA bars=window+1000; extra cases isolate no history, constant compression, one varying plot and four varying plots",
        "probesExecuted": False,
    }
    save(D / "capacity-plan.json", plan)
    return plan


def phase(name, binding):
    path = D / f"phase-{name}.json"
    value = read(path)
    if (value.get("phase") != name or value.get("status") != "passed"
            or value.get("returncode") != 0
            or value.get("before") != binding or value.get("after") != binding):
        raise ValueError("Required phase did not pass against frozen source: " + name)
    if value.get("wrapperSha256") != sha(D / "run_phase.py"):
        raise ValueError("Phase wrapper identity differs: " + name)
    if value.get("wrapperLogSha256") != sha(D / f"phase-{name}-wrapper.log"):
        raise ValueError("Phase wrapper log differs: " + name)
    if name.startswith("gate-"):
        log, exit_path = D / (name + ".log"), D / (name + ".exit")
        hashes = {"gateLogSha256": sha(log), "gateExitSha256": sha(exit_path)}
    elif name == "release":
        log, exit_path = D / "build-release.log", D / "build-release.exit"
        hashes = {"buildLogSha256": sha(log), "buildExitSha256": sha(exit_path)}
    else:
        exit_path = D / "link-capacity-after.exit"
        hashes = {"linkReceiptSha256": sha(D / "identity-capacity-after.json"),
                  "linkLogSha256": sha(D / "link-capacity-after.log")}
    if int(exit_path.read_text(encoding="utf-8-sig")) != 0:
        raise ValueError("Required phase exit is nonzero: " + name)
    if any(value.get(key) != expected for key, expected in hashes.items()):
        raise ValueError("Required phase artifact differs: " + name)
    return {"path": str(path), "sha256": sha(path), "artifactHashes": hashes}


def identity(tag):
    path = D / f"identity-capacity-{tag}.json"
    value = read(path)
    binary, probe = D / f"capacity-{tag}.exe", D / "capacity_probe.rs"
    manifest_path = D / ("before-source-identity.json" if tag == "before" else "source-identity.json")
    if (value.get("tag") != tag or value.get("probe") != "capacity"
            or sha(binary) != value["executableSha256"]
            or sha(probe) != value["sourceSha256"]
            or sha(manifest_path) != value["sourceManifestSha256"]):
        raise ValueError("Exact source/binary/link identity differs: " + tag)
    paths = value["libraryHashes"]
    expected_names = {"libpine_runtime.rlib", "libpine_sema.rlib", "libpine_syntax.rlib"}
    if len(paths) != 4 or not expected_names.issubset({Path(p).name for p in paths}):
        raise ValueError("Expected 3 Pine libraries and serde_json")
    if not any(Path(p).name.startswith("libserde_json-") for p in paths):
        raise ValueError("Missing exact serde_json library")
    archive = read(D / "before-binary-identity.json") if tag == "before" else None
    if archive is not None and archive["beforeManifestSha256"] != sha(manifest_path):
        raise ValueError("Archived baseline source binding differs")
    for rawpath, expected in paths.items():
        actual = Path(rawpath)
        actual = actual if actual.is_absolute() else ROOT / actual
        if sha(actual) != expected:
            raise ValueError("Exact linked library differs: " + rawpath)
        if archive is not None:
            if not actual.resolve().is_relative_to((D / "baseline").resolve()):
                raise ValueError("Before link uses a nonarchived library")
            matched = [entry for entry in archive["libraries"].values()
                       if Path(entry["archive"]).resolve() == actual.resolve()
                       and entry["sha256"] == expected]
            if len(matched) != 1:
                raise ValueError("Before link library lacks unique archive identity")
    return {"binary": str(binary), "binarySha256": sha(binary),
            "sourceSha256": sha(probe), "sourceManifestSha256": sha(manifest_path),
            "linkReceipt": str(path), "linkReceiptSha256": sha(path), "link": value}


def no_other_measurements():
    # Record only process names/IDs if rejecting. Command lines are neither
    # printed nor persisted. The coordinator separately keeps WSL quiescent.
    command = (
        "$ErrorActionPreference = 'Stop'; "
        "Get-CimInstance Win32_Process | Where-Object { "
        f"$_.ProcessId -ne {os.getpid()} -and ("
        "$_.Name -match '^(cargo|rustc|maturin|link|cl|msbuild|pine.*|serialization.*|capacity.*|valuewhen.*|heap.*|differential.*)\\.exe$' "
        "-or ($_.Name -match '^(python|pythonw)\\.exe$' -and "
        "$_.CommandLine -match '(serialization_runner|capacity_runner|valuewhen_runner)\\.py')) "
        "} | Select-Object Name,ProcessId | ConvertTo-Json"
    )
    checked = subprocess.run(["powershell.exe", "-NoProfile", "-Command", command],
                             cwd=ROOT, capture_output=True, timeout=30)
    if checked.returncode != 0:
        raise ValueError("Could not verify build/measurement quiescence")
    if checked.stdout.decode("utf-8-sig").strip():
        raise ValueError("Another build, validation, or measurement process is active")
    return {"matchingWindowsBuildOrMeasurementProcesses": [],
            "limitation": "Coordinator keeps WSL builds and other measurements quiescent; this is not proof of OS inactivity or an interprocess lock."}


def prerequisites(prepared):
    manifest_path = D / "source-identity.json"
    manifest = read(manifest_path)
    changed = [path for path, expected in manifest["files"].items()
               if not (ROOT / path).is_file() or sha(ROOT / path) != expected]
    if changed:
        raise ValueError("Frozen source differs: " + repr(changed))
    binding = {"manifestSha256": sha(manifest_path),
               "archiveSha256": sha(D / "source.tar"),
               "files": len(manifest["files"]), "sourceVerified": True}
    phases = {name: phase(name, binding) for name in PHASE_NAMES}
    identities = {tag: identity(tag) for tag in ("before", "after")}
    if identities["before"]["sourceSha256"] != identities["after"]["sourceSha256"]:
        raise ValueError("Before/after wrapper source differs")
    if identities["after"]["sourceManifestSha256"] != binding["manifestSha256"]:
        raise ValueError("After link differs from final frozen source")
    if prepared["probeSource"]["sha256"] != identities["after"]["sourceSha256"]:
        raise ValueError("Plan probe source differs from exact link")
    baseline_path = D / "before-binary-identity.json"
    baseline = read(baseline_path)
    baseline_archive = D / "before-source.tar"
    if baseline["beforeArchiveSha256"] != sha(baseline_archive):
        raise ValueError("Baseline source archive differs")
    for item in baseline["libraries"].values():
        if sha(Path(item["archive"])) != item["sha256"]:
            raise ValueError("Baseline compiler artifact differs")
    for case in prepared["cases"]:
        if sha(Path(case["source"]["path"])) != case["source"]["sha256"]:
            raise ValueError("Prepared Pine fixture changed")
    schema = prepared["profileSchema"]
    if sha(PROFILE_SOURCE) != schema["sha256"] or profile_fields() != schema["fields"]:
        raise ValueError("Complete public profile schema changed")
    return {"sourceBinding": binding, "phases": phases, "identities": identities,
            "baselineArchive": {"identitySha256": sha(baseline_path),
                                "sourceArchiveSha256": sha(baseline_archive),
                                "compilerArtifacts": len(baseline["libraries"])},
            "quiescence": no_other_measurements()}


def quarter_prefix(end):
    cycles, remainder = divmod(end, 17)
    return cycles * 136 + remainder * (remainder - 1) // 2


def oracle(case):
    kind, bars, window = case["kind"], case["bars"], case["window"]
    ticks = start = end = None
    close = (400 + (bars - 1) % 17) / 4.0 if bars else 0.0
    if kind == "sma":
        end, start = bars, bars - window
        ticks = 400 * window + quarter_prefix(end) - quarter_prefix(start)
        values = [(float(ticks) / 4.0) / window]
    else:
        values = {"empty": [], "constant": [71.25], "close": [close],
                  "multiClose": [close, close * 2.0, close + 1.0, -close]}[kind]
    return {"tailBits": [struct.pack("!d", value).hex() for value in values],
            "quarterTicks": ticks, "start": start, "end": end}


def parse_metrics(raw, case, schema):
    lines = raw.splitlines()
    if len(lines) != 1 or not lines[0]:
        raise ValueError("Expected exactly one capacity JSON line")
    metrics = loads(lines[0])
    if not isinstance(metrics, dict) or set(metrics) != TOP:
        raise ValueError("Unknown or missing capacity metric field")
    expected = {
        "probe": "publicProfileAppendCapacity", "source": case["source"]["path"],
        "kind": case["kind"], "window": case["window"], "bars": case["bars"],
        "groups": GROUPS, "callsPerGroup": CALLS, "timedCalls": GROUPS * CALLS,
        "warmupCalls": WARMUP, "profileUnchanged": True,
        "plotValues": [case["bars"]] * case["plots"],
        "measurementScope": "31 groups of 256 public HistoricalRuntime::profile calls; full profile and runtime reference are black-boxed",
        "profileScope": "all fields emitted by public_runtime_profiled_result_json",
        "oracle": "direct integer quarter-tick sum for SMA; direct constant or final-close formulas for other plots; empty fixture has no bars or plots",
    }
    for key, value in expected.items():
        if type(metrics[key]) is not type(value) or metrics[key] != value:
            raise ValueError("Unexpected capacity fixture field: " + key)
    for field in TIMINGS:
        numeric(metrics[field], positive=field == "profileMedianPerCallNs")
    groups = metrics["groupMs"]
    if not isinstance(groups, list) or len(groups) != GROUPS:
        raise ValueError("Expected 31 raw timing groups")
    for value in groups:
        numeric(value, positive=True)
    computed = statistics.median(groups) * 1_000_000.0 / CALLS
    if struct.pack("!d", float(metrics["profileMedianPerCallNs"])) != struct.pack("!d", computed):
        raise ValueError("Profile median does not exactly recompute")
    proof = oracle(case)
    for key, value in (("plotTailBits", proof["tailBits"]),
                       ("oracleTailBits", proof["tailBits"]),
                       ("oracleIntegerQuarterTicks", proof["quarterTicks"]),
                       ("oracleWindowStart", proof["start"]),
                       ("oracleWindowEndExclusive", proof["end"])):
        if type(metrics[key]) is not type(value) or metrics[key] != value:
            raise ValueError("Independent tail bit oracle differs: " + key)
    if any(type(length) is not int for length in metrics["plotValues"]):
        raise ValueError("Noninteger plot length")
    profile = metrics["profile"]
    if not isinstance(profile, dict) or sorted(profile) != schema["fields"]:
        raise ValueError("Complete public profile counters missing or unexpected")
    if integer(metrics["profileFieldCount"]) != len(schema["fields"]):
        raise ValueError("Full profile field count differs")
    for key, value in profile.items():
        if key == "historyRetentionMode":
            if value not in {"staticTrimmed", "dynamicFull", "maxBarsBack"}:
                raise ValueError("Unexpected history retention mode")
        elif key == "historyHasDynamicOffsets":
            if type(value) is not bool:
                raise ValueError("Expected boolean history flag")
        elif value is None and key in {"historyMaxBarsBack", "historyDynamicRetentionMaxMissedOffset"}:
            continue
        elif integer(value) < 0:
            raise ValueError("Negative public profile counter")
    if (profile["bars"] != case["bars"] or profile["plots"] != case["plots"]
            or profile["plotValues"] != case["bars"] * case["plots"]):
        raise ValueError("Public bar/plot counts differ")
    return metrics, proof


def summary(cases, records):
    result = {}
    for case in cases:
        by_tag = {tag: [row for row in records
                        if row["case"] == case["name"] and row["tag"] == tag]
                  for tag in ("before", "after")}
        if any(len(rows) != REPETITIONS for rows in by_tag.values()):
            raise ValueError("Incomplete fresh-process repetitions")
        reference = by_tag["before"][0]["metrics"]["profile"]
        if any(row["metrics"]["profile"] != reference
               for rows in by_tag.values() for row in rows):
            raise ValueError("Complete profiles differ across versions or repetitions")
        timings = {}
        for name in TIMINGS:
            before = [row["metrics"][name] for row in by_tag["before"]]
            after = [row["metrics"][name] for row in by_tag["after"]]
            bm, am = statistics.median(before), statistics.median(after)
            timings[name] = {"unit": "ns/call" if name == "profileMedianPerCallNs" else "ms",
                "beforeSamples": before, "afterSamples": after,
                "beforeMedian": bm, "afterMedian": am,
                "beforeMin": min(before), "beforeMax": max(before),
                "afterMin": min(after), "afterMax": max(after),
                "afterBeforeRatio": am / bm if bm else None}
        result[case["name"]] = {"kind": case["kind"], "window": case["window"],
            "bars": case["bars"], "plots": case["plots"], "timings": timings,
            "fullProfile": reference, "profileFieldCount": len(reference),
            "beforeAfterAllProfileFieldsEqual": True, "oracle": oracle(case),
            "profileGroupMs": {tag: [row["metrics"]["groupMs"] for row in rows]
                               for tag, rows in by_tag.items()}}
    return result


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    modes = ap.add_mutually_exclusive_group(required=True)
    modes.add_argument("--prepare-only", action="store_true")
    modes.add_argument("--execute", action="store_true")
    ap.add_argument("--timeout", type=float, default=300)
    args = ap.parse_args()
    numeric(args.timeout, positive=True)
    prepared = prepare()
    planned = prepared["plannedProcesses"]
    if args.prepare_only:
        print(f"Prepared 9 cases / {planned} processes; no builds or probes executed.")
        return
    initial = prerequisites(prepared)
    plan_path, runner_path = D / "capacity-plan.json", Path(__file__)
    plan_sha, runner_sha, common_sha = sha(plan_path), sha(runner_path), sha(D / "evidence_common.py")
    out = directory("capacity")
    copied_cases = []
    for case in prepared["cases"]:
        original = case["source"]
        frozen = out / "sources" / Path(original["path"]).name
        frozen.parent.mkdir(parents=True, exist_ok=True)
        frozen.write_bytes(Path(original["path"]).read_bytes())
        if sha(frozen) != original["sha256"]:
            raise ValueError("Frozen Pine fixture copy differs")
        copied_cases.append({**case, "originalSource": original,
                             "source": {"path": str(frozen), "sha256": sha(frozen)}})
    receipt = {
        "status": "running", "startedUtc": datetime.now(timezone.utc).isoformat(),
        "plannedProcesses": planned, "completedProcesses": 0,
        "method": "9 fixed cases; 3 fresh processes per version; paired order alternates by repetition; all processes sequential",
        "prerequisites": initial, "runnerSha256": runner_sha,
        "helperHashes": {"evidence_common.py": common_sha},
        "plan": {"path": str(plan_path), "sha256": plan_sha},
        "profileSchema": prepared["profileSchema"], "cases": copied_cases, "records": [],
        "limits": [
            "Timed calls include all public HistoricalRuntime::profile work, including remaining collection and nested-state walks.",
            "Analysis, seed, result observation, encoder work and receipt writes are outside timed profile groups; all control samples are retained.",
            "resultObservationMs includes view construction, tail iteration/bit checks and disposal; it is not pure view construction.",
            "Three fresh-process medians are descriptive, not confidence intervals, whole-process RSS or full resource matrix qualification.",
            "No-history, compressed constant, varying single-plot and four-plot controls distinguish source paths; seed work is not zero-overhead qualified.",
        ],
    }
    save(out / "progress.json", receipt)
    try:
        for repetition in range(REPETITIONS):
            for case in copied_cases:
                pair = {}
                tags = ("before", "after") if repetition % 2 == 0 else ("after", "before")
                for tag in tags:
                    no_other_measurements()
                    stem = f'{case["name"]}-{tag}-{repetition}'
                    metrics_file = out / (stem + ".metrics.json")
                    command = [initial["identities"][tag]["binary"], case["source"]["path"],
                               case["kind"], str(case["bars"]), str(case["window"]), str(metrics_file)]
                    run, raw = execute(out, stem, command, args.timeout)
                    row = {"case": case["name"], "tag": tag, "repetition": repetition,
                           "source": case["source"], "run": run}
                    receipt["records"].append(row)
                    receipt["completedProcesses"] = sum(r["run"]["returncode"] == 0 for r in receipt["records"])
                    save(out / "progress.json", receipt)
                    if run["returncode"] != 0:
                        raise RuntimeError("Capacity process failed: " + stem)
                    if Path(run["stderr"]).read_bytes():
                        raise ValueError("Unexpected capacity stderr: " + stem)
                    if metrics_file.read_bytes() != raw.rstrip(b"\r\n"):
                        raise ValueError("Metrics file differs from raw stdout")
                    row["metrics"], row["pythonOracle"] = parse_metrics(raw, case, prepared["profileSchema"])
                    row["rawMetrics"] = {"path": str(metrics_file), "sha256": sha(metrics_file),
                                         "bytes": metrics_file.stat().st_size}
                    pair[tag] = row
                    save(out / "progress.json", receipt)
                    print(stem, "profileNsPerCall", row["metrics"]["profileMedianPerCallNs"], flush=True)
                if pair["before"]["metrics"]["profile"] != pair["after"]["metrics"]["profile"]:
                    raise ValueError("Paired complete public profile differs")
                pair["after"]["beforeComparison"] = {"allPublicProfileFieldsEqual": True,
                    "tailBitsEqualToIndependentOracle": True,
                    "beforeStdoutSha256": pair["before"]["run"]["stdoutSha256"],
                    "afterStdoutSha256": pair["after"]["run"]["stdoutSha256"]}
                save(out / "progress.json", receipt)
        if prerequisites(prepared) != initial:
            raise ValueError("Final source/gates/links/libraries/quiescence differ")
        if sha(plan_path) != plan_sha or sha(runner_path) != runner_sha or sha(D / "evidence_common.py") != common_sha:
            raise ValueError("Plan/runner/helper changed during measurement")
        for case in copied_cases:
            if sha(Path(case["source"]["path"])) != case["source"]["sha256"]:
                raise ValueError("Frozen Pine fixture changed")
        for row in receipt["records"]:
            for name in ("stdout", "stderr", "exit"):
                if sha(Path(row["run"][name])) != row["run"][name + "Sha256"]:
                    raise ValueError("Raw subprocess receipt changed")
            if sha(Path(row["rawMetrics"]["path"])) != row["rawMetrics"]["sha256"]:
                raise ValueError("Raw metrics file changed")
        receipt.update(status="passed", finishedUtc=datetime.now(timezone.utc).isoformat(),
            completedProcesses=planned, rawTimingValues=planned * len(TIMINGS),
            pairedTimingMedians=len(copied_cases) * len(TIMINGS),
            rawProfileGroupTimingValues=planned * GROUPS, timedProfileCalls=planned * GROUPS * CALLS,
            fullProfileComparisons=len(copied_cases) * REPETITIONS,
            uniqueSmaOracleCases=len(WINDOWS), uniqueTailOracleCases=len(copied_cases),
            summary=summary(copied_cases, receipt["records"]))
        save(out / "summary.json", receipt)
        save(D / "capacity-results.json", receipt)
        print(f"PASS 9 cases / {planned} fresh processes / {planned * GROUPS} groups / {planned * GROUPS * CALLS} timed calls", flush=True)
    except BaseException as error:
        receipt.update(status="failed", error=repr(error), attemptedProcesses=len(receipt["records"]))
        save(out / "failure.json", receipt)
        save(out / "progress.json", receipt)
        raise


if __name__ == "__main__":
    main()

