"""Prepare/fresh-process valuewhen public API observations; never build/link.

Original per-call allocation/time metrics, all repeated samples, raw public
payloads, independent plot oracles and complete public profiles are retained.
"""
from __future__ import annotations
import argparse
from datetime import datetime, timezone
import math
from pathlib import Path
import re
import statistics
import struct

import capacity_runner as capacity
from evidence_common import D, ROOT, directory, execute, loads, read, save, sha, source

REPETITIONS, SAMPLES = 3, 9
METRIC_FIELDS = {"ms", "allocatedBytes", "allocations", "peakAdditionalLiveBytes", "liveDeltaBytes"}
SINGLE_STAGES = {"analyze", "historicalSeed", "realtimeSeedWithoutOutput",
                 "confirmedWithoutOutput", "nextHistoricalWithoutOutput"}
REPEATED_STAGES = {"historicalClone", "historicalAppendSharedClone",
                   "formingWithoutOutput", "formingApplyUpdate"}
PROFILE_FIELDS = ("seedProfile", "confirmedProfile", "finalProfile")
STRATEGY_FORMING_PASSES = {"seedProfile": 0, "confirmedProfile": 2 * SAMPLES,
                          "finalProfile": 2 * SAMPLES}
DIFF_PROFILE = "valuewhenStateValueCapacity"
FNV_OFFSET, FNV_MULTIPLIER, U64 = 0xCBF29CE484222325, 0x100000001B3, (1 << 64) - 1
TOP = {
    "probe", "case", "bars", "pineSource", "samplesPerRepeatedStage", "stages",
    *PROFILE_FIELDS, "formingChecks", "seedOracle", "confirmedOracle", "finalOracle",
    "seededRevision", "publicRevision", "rawPayloadFiles", "allowedBeforeAfterProfileDifferences",
    "oracle", "measurementScope", "strategyTrigger", "limitations",
}


def cases():
    return [
        {"name": f"dynamic{bars}", "case": "dynamic", "bars": bars}
        for bars in (1000, 10_000, 100_000)
    ] + [
        {"name": "sparse100000", "case": "sparse", "bars": 100_000},
        {"name": "fixed0_100000", "case": "fixed0", "bars": 100_000},
        {"name": "fixed1_100000", "case": "fixed1", "bars": 100_000},
        {"name": "none100000", "case": "none", "bars": 100_000},
        {"name": "strategy5000", "case": "strategy", "bars": 5000},
        {"name": "strategy20000", "case": "strategy", "bars": 20_000},
    ]


def scripts():
    # Record the exact embedded input text independently in a frozen .pine
    # file. The Python event-index oracle below is independent of this parser.
    text = (D / "valuewhen_probe.rs").read_text(encoding="utf8")
    found = re.findall(r'^\s*"(none|dynamic|sparse|fixed0|fixed1|strategy)"\s*=>\s*(?:\{\s*)?"((?:[^"\\]|\\.)*)"',
                       text, re.MULTILINE)
    result = {}
    for name, raw in found:
        if name in result:
            raise ValueError("Duplicate embedded Pine fixture")
        result[name] = loads('"' + raw + '"')
    if set(result) != {case["case"] for case in cases()}:
        raise ValueError("Expected all six final embedded Pine fixtures")
    return result


def prepare():
    texts = scripts()
    prepared = cases()
    for case in prepared:
        case["pineSource"] = texts[case["case"]]
        case["source"] = source(D / ("valuewhen-" + case["name"] + ".pine"), case["pineSource"])
    result = {
        "cases": prepared, "repetitionsPerVersion": REPETITIONS,
        "plannedProcesses": len(prepared) * REPETITIONS * 2,
        "samplesPerRepeatedStage": SAMPLES,
        "singleStages": sorted(SINGLE_STAGES), "repeatedStages": sorted(REPEATED_STAGES),
        "metricFields": sorted(METRIC_FIELDS),
        "probeSource": {"path": str(D / "valuewhen_probe.rs"),
                        "sha256": sha(D / "valuewhen_probe.rs")},
        "profileSchema": {"path": str(capacity.PROFILE_SOURCE),
                          "sha256": sha(capacity.PROFILE_SOURCE), "fields": capacity.profile_fields()},
        "allowedBeforeAfterProfileDifferences": [DIFF_PROFILE],
        "strategyProfileAdditionalFormingPasses": STRATEGY_FORMING_PASSES,
        "method": "Every sample is preserved; repeated-stage process median precedes the median of three fresh processes; paired before/after execution order alternates by repetition",
        "scope": "Named public API calls and allocator-request counts; no process RSS or isolated valuewhen-only attribution",
        "probesExecuted": False,
    }
    save(D / "valuewhen-plan.json", result)
    return result


def identity(tag):
    path = D / f"identity-valuewhen-{tag}.json"
    value = read(path)
    binary, probe = D / f"valuewhen-{tag}.exe", D / "valuewhen_probe.rs"
    manifest_path = D / ("before-source-identity.json" if tag == "before" else "source-identity.json")
    link_log, link_exit = D / f"link-valuewhen-{tag}.log", D / f"link-valuewhen-{tag}.exit"
    if int(link_exit.read_text(encoding="utf-8-sig")) != 0:
        raise ValueError("Valuewhen link exit is nonzero: " + tag)
    if (value.get("tag") != tag or value.get("probe") != "valuewhen"
            or sha(binary) != value["executableSha256"]
            or sha(probe) != value["sourceSha256"]
            or sha(manifest_path) != value["sourceManifestSha256"]):
        raise ValueError("Exact valuewhen source/binary/link identity differs: " + tag)
    paths = value["libraryHashes"]
    names = {Path(path).name for path in paths}
    if (len(paths) != 4 or not {"libpine_runtime.rlib", "libpine_sema.rlib", "libpine_syntax.rlib"}.issubset(names)
            or not any(name.startswith("libserde_json-") for name in names)):
        raise ValueError("Expected 3 Pine libraries and one exact serde_json library")
    archive = read(D / "before-binary-identity.json") if tag == "before" else None
    if archive is not None and archive["beforeManifestSha256"] != sha(manifest_path):
        raise ValueError("Archived baseline source binding differs")
    for rawpath, expected in paths.items():
        actual = Path(rawpath)
        actual = actual if actual.is_absolute() else ROOT / actual
        if sha(actual) != expected:
            raise ValueError("Exact linked library differs: " + rawpath)
        if archive is not None:
            if not actual.resolve().is_relative_to((D / "baseline").resolve()):
                raise ValueError("Before valuewhen link uses a nonarchived library")
            matched = [entry for entry in archive["libraries"].values()
                       if Path(entry["archive"]).resolve() == actual.resolve() and entry["sha256"] == expected]
            if len(matched) != 1:
                raise ValueError("Before link library lacks unique archival identity")
    return {"binary": str(binary), "binarySha256": sha(binary), "sourceSha256": sha(probe),
            "sourceManifestSha256": sha(manifest_path), "linkReceipt": str(path),
            "linkReceiptSha256": sha(path), "linkLogSha256": sha(link_log),
            "linkExitSha256": sha(link_exit), "link": value}


def prerequisites(prepared):
    manifest_path = D / "source-identity.json"
    manifest = read(manifest_path)
    changed = [path for path, expected in manifest["files"].items()
               if not (ROOT / path).is_file() or sha(ROOT / path) != expected]
    if changed:
        raise ValueError("Frozen source differs: " + repr(changed))
    binding = {"manifestSha256": sha(manifest_path), "archiveSha256": sha(D / "source.tar"),
               "files": len(manifest["files"]), "sourceVerified": True}
    phases = {name: capacity.phase(name, binding) for name in ("gate-windows", "gate-linux", "release")}
    phase_name = "link-valuewhen-after"
    phase_path = D / ("phase-" + phase_name + ".json")
    phase = read(phase_path)
    if (phase.get("phase") != phase_name or phase.get("status") != "passed"
            or phase.get("returncode") != 0 or phase.get("before") != binding or phase.get("after") != binding
            or phase.get("wrapperSha256") != sha(D / "run_phase.py")
            or phase.get("wrapperLogSha256") != sha(D / ("phase-" + phase_name + "-wrapper.log"))
            or phase.get("linkReceiptSha256") != sha(D / "identity-valuewhen-after.json")
            or phase.get("linkLogSha256") != sha(D / "link-valuewhen-after.log")
            or int((D / "link-valuewhen-after.exit").read_text(encoding="utf-8-sig")) != 0):
        raise ValueError("Valuewhen after link phase not bound to passing frozen source")
    phases[phase_name] = {"path": str(phase_path), "sha256": sha(phase_path),
        "artifactHashes": {"linkReceiptSha256": sha(D / "identity-valuewhen-after.json"),
                           "linkLogSha256": sha(D / "link-valuewhen-after.log")}}
    identities = {tag: identity(tag) for tag in ("before", "after")}
    if identities["before"]["sourceSha256"] != identities["after"]["sourceSha256"]:
        raise ValueError("Before/after valuewhen probe source differs")
    if (identities["after"]["sourceManifestSha256"] != binding["manifestSha256"]
            or identities["after"]["sourceSha256"] != prepared["probeSource"]["sha256"]):
        raise ValueError("Valuewhen final link and plan/source binding differ")
    baseline_path = D / "before-binary-identity.json"
    baseline = read(baseline_path)
    if baseline["beforeArchiveSha256"] != sha(D / "before-source.tar"):
        raise ValueError("Baseline source archive differs")
    for item in baseline["libraries"].values():
        if sha(Path(item["archive"])) != item["sha256"]:
            raise ValueError("Archived compiler artifact differs")
    for case in prepared["cases"]:
        if sha(Path(case["source"]["path"])) != case["source"]["sha256"]:
            raise ValueError("Frozen Pine input differs")
    schema = prepared["profileSchema"]
    if sha(capacity.PROFILE_SOURCE) != schema["sha256"] or capacity.profile_fields() != schema["fields"]:
        raise ValueError("Complete public profile schema differs")
    return {"sourceBinding": binding, "phases": phases, "identities": identities,
        "baselineArchive": {"identitySha256": sha(baseline_path),
                            "sourceArchiveSha256": sha(D / "before-source.tar"),
                            "compilerArtifacts": len(baseline["libraries"])},
        "quiescence": capacity.no_other_measurements()}


def expected(case, index, replacement=None):
    kind = case["case"]
    if kind in {"none", "fixed0"}:
        event = index
    elif kind == "fixed1":
        event = index - 1
    elif kind in {"dynamic", "strategy"}:
        event = index - index % 5000
    elif kind == "sparse":
        event = (index // 257 - index % 17) * 257
    else:
        raise ValueError("Unknown event oracle case")
    if event < 0:
        return None
    if replacement is not None and event == replacement[0]:
        return replacement[1]
    return (400 + event) / 4.0


def bits(value):
    return "ffffffffffffffff" if value is None else struct.pack("!d", value).hex()


def events(case, bars):
    return {"none": 0, "fixed0": min(bars, 1), "fixed1": min(bars, 2),
            "dynamic": min(bars, 1_000_000), "strategy": min(bars, 1_000_000),
            "sparse": min((bars - 1) // 257 + 1 if bars else 0, 1_000_000)}[case["case"]]


def oracle(case, bars, replacement=None):
    fnv, na = FNV_OFFSET, 0
    for index in range(bars):
        value = expected(case, index, replacement)
        na += value is None
        raw = U64.to_bytes(8, "little") if value is None else struct.pack("<d", value)
        for byte in raw:
            fnv = ((fnv ^ byte) * FNV_MULTIPLIER) & U64
    return {"plotValues": bars, "naValues": na, "allValuesMatchDirectOracle": True,
            "fnv1a64ValueBitsLe": f"{fnv:016x}"}


def check_profile(profile, case, bars, schema, phase):
    if phase not in STRATEGY_FORMING_PASSES:
        raise ValueError("Unknown profile observation phase")
    if not isinstance(profile, dict) or sorted(profile) != schema["fields"]:
        raise ValueError("Complete public profile fields missing or unexpected")
    for key, value in profile.items():
        if key == "historyRetentionMode":
            if value not in {"staticTrimmed", "dynamicFull", "maxBarsBack"}:
                raise ValueError("Unexpected history retention mode")
        elif key == "historyHasDynamicOffsets":
            if type(value) is not bool:
                raise ValueError("Expected boolean history flag")
        elif value is None and key in {"historyMaxBarsBack", "historyDynamicRetentionMaxMissedOffset"}:
            continue
        elif capacity.integer(value) < 0:
            raise ValueError("Negative public profile counter")
    counters = {"bars": bars, "plots": 1, "plotValues": bars,
                "valuewhenStateValues": events(case, bars),
                "valuewhenStateSlots": int(case["case"] != "none")}
    for key, value in counters.items():
        if profile[key] != value:
            raise ValueError("Independent public counter oracle differs: " + key)
    if profile[DIFF_PROFILE] < counters["valuewhenStateValues"]:
        raise ValueError("Numeric event storage capacity below retained event count")
    if case["case"] == "none" and profile[DIFF_PROFILE] != 0:
        raise ValueError("No-valuewhen control reports event storage")
    if case["case"] == "strategy":
        # Successful forming updates retain scheduler totals while Pine state
        # rolls back. The 9 without-output + 9 apply updates add 18 executions
        # to confirmed/final observations; seed precedes these updates.
        expected_passes = bars + STRATEGY_FORMING_PASSES[phase]
        if profile["strategyScriptPasses"] != expected_passes or profile["strategyRecalculationPasses"] != 0:
            raise ValueError("No-fill strategy script/recalculation counters diverged")


def check_stage(stage):
    if not isinstance(stage, dict) or set(stage) != METRIC_FIELDS:
        raise ValueError("Unexpected per-call metric schema")
    capacity.numeric(stage["ms"])
    for key in METRIC_FIELDS - {"ms"}:
        value = capacity.integer(stage[key])
        if key != "liveDeltaBytes" and value < 0:
            raise ValueError("Negative allocator request count")
    if stage["peakAdditionalLiveBytes"] < max(stage["liveDeltaBytes"], 0):
        raise ValueError("Additional live allocator peak below final live delta")


def parse_metrics(raw, case, schema):
    lines = raw.splitlines()
    if len(lines) != 1 or not lines[0]:
        raise ValueError("Expected one valuewhen receipt line")
    metrics = loads(lines[0])
    if not isinstance(metrics, dict) or set(metrics) != TOP:
        raise ValueError("Missing or unknown valuewhen receipt field")
    for key, value in {"probe": "publicValuewhenPersistentHistory", "case": case["case"],
                       "bars": case["bars"], "pineSource": case["pineSource"],
                       "samplesPerRepeatedStage": SAMPLES,
                       "allowedBeforeAfterProfileDifferences": [DIFF_PROFILE],
                       "strategyTrigger": ("calc_on_order_fills=true creates/restores a checkpoint per historical script bar; no orders or fills in this fixture"
                                           if case["case"] == "strategy" else "not a strategy")}.items():
        if type(metrics[key]) is not type(value) or metrics[key] != value:
            raise ValueError("Unexpected valuewhen fixture field: " + key)
    stages = metrics["stages"]
    if not isinstance(stages, dict) or set(stages) != SINGLE_STAGES | REPEATED_STAGES:
        raise ValueError("Unexpected named public API stages")
    for name, stage in stages.items():
        if name in SINGLE_STAGES:
            check_stage(stage)
        else:
            if not isinstance(stage, list) or len(stage) != SAMPLES:
                raise ValueError("Expected all nine original stage samples")
            for sample in stage:
                check_stage(sample)
    count = case["bars"]
    proofs = {"seedOracle": oracle(case, count),
              "confirmedOracle": oracle(case, count + 1, (count, (400 + count) / 4.0 + 0.375)),
              "finalOracle": oracle(case, count + 2, (count, (400 + count) / 4.0 + 0.375))}
    for key, proof in proofs.items():
        if metrics[key] != proof or any(type(metrics[key][name]) is not type(value) for name, value in proof.items()):
            raise ValueError("Independent complete plot oracle differs: " + key)
    for name, bars in zip(PROFILE_FIELDS, (count, count + 1, count + 2)):
        check_profile(metrics[name], case, bars, schema, name)
    checks = metrics["formingChecks"]
    if not isinstance(checks, list) or len(checks) != SAMPLES * 2:
        raise ValueError("Expected eighteen forming correctness observations")
    for index, observed in enumerate(checks):
        method = "update_without_output" if index < SAMPLES else "apply_update"
        sample = index % SAMPLES
        replacement = ((400 + count) / 4.0 + (sample + 1) / 8.0
                       if index < SAMPLES else (400 + count) / 4.0 - (sample + 1) / 8.0)
        wanted = {"method": method, "sample": sample,
                  "oracleBits": bits(expected(case, count, (count, replacement))),
                  "previewEvents": events(case, count + 1), "confirmedEvents": events(case, count),
                  "revision": index + 2}
        if not isinstance(observed, dict) or set(observed) != set(wanted):
            raise ValueError("Unexpected forming correctness schema")
        if any(type(observed[key]) is not type(value) or observed[key] != value for key, value in wanted.items()):
            raise ValueError("Independent forming revision/event/tail oracle differs")
    if capacity.integer(metrics["publicRevision"]) != 2 * SAMPLES + 3:
        raise ValueError("Final public revision differs")
    if capacity.integer(metrics["seededRevision"]) != 1:
        raise ValueError("Seed public revision differs")
    return metrics, proofs


def check_snapshot(document, case, bars, replacement):
    if not isinstance(document, dict) or not isinstance(document.get("plots"), list) or len(document["plots"]) != 1:
        raise ValueError("Expected exactly one public snapshot plot")
    plot = document["plots"][0]
    if not isinstance(plot, dict) or not isinstance(plot.get("values"), list) or len(plot["values"]) != bars:
        raise ValueError("Unexpected public plot history length")
    fnv, na = FNV_OFFSET, 0
    for index, actual in enumerate(plot["values"]):
        wanted = expected(case, index, replacement)
        if wanted is None:
            if actual is not None:
                raise ValueError("Public plot NA differs from independent event oracle")
            na += 1
            raw = U64.to_bytes(8, "little")
        else:
            if isinstance(actual, bool) or not isinstance(actual, (int, float)) or not math.isfinite(actual):
                raise ValueError("Expected a finite public plot scalar")
            raw = struct.pack("<d", float(actual))
            if raw != struct.pack("<d", wanted):
                raise ValueError("Public plot IEEE bits differ from independent event oracle")
        for byte in raw:
            fnv = ((fnv ^ byte) * FNV_MULTIPLIER) & U64
    return {"plotId": capacity.integer(plot["id"]), "plotValues": bars,
            "naValues": na, "fnv1a64ValueBitsLe": f"{fnv:016x}",
            "allValuesMatchIndependentPythonOracle": True}


def raw_payloads(metrics, metrics_file, case):
    names = ["seed"] + [f"forming-apply-{sample}" for sample in range(SAMPLES)] + ["confirmed", "next-historical"]
    files = metrics["rawPayloadFiles"]
    expected_paths = [str(metrics_file.with_suffix("." + name + ".json")) for name in names]
    if type(files) is not list or files != expected_paths:
        raise ValueError("Raw public payload locators differ from process receipt")
    result = {}
    count, price = case["bars"], (400 + case["bars"]) / 4.0
    plot_id = None
    for name, rawpath in zip(names, files):
        path = Path(rawpath)
        document = read(path)
        item = {"path": str(path), "sha256": sha(path), "bytes": path.stat().st_size}
        if name in {"seed", "confirmed", "next-historical"}:
            bars = count + {"seed": 0, "confirmed": 1, "next-historical": 2}[name]
            replacement = None if name == "seed" else (count, price + 0.375)
            item["pythonOracle"] = check_snapshot(document, case, bars, replacement)
            current_id = item["pythonOracle"]["plotId"]
            if plot_id is not None and current_id != plot_id:
                raise ValueError("Public plot identity changed across snapshots")
            plot_id = current_id
        else:
            sample = int(name.rsplit("-", 1)[1])
            if (not isinstance(document, dict) or document.get("visibility") != "preview"
                    or capacity.integer(document.get("revision")) != SAMPLES + sample + 2
                    or not isinstance(document.get("series"), list)):
                raise ValueError("Public forming delta revision/visibility/schema differs")
            checked = 0
            replacement = (count, price - (sample + 1) / 8.0)
            for change in document["series"]:
                if not isinstance(change, dict) or change.get("family") != "plot" or change.get("id") != plot_id:
                    raise ValueError("Unexpected forming delta series identity")
                start = capacity.integer(change.get("start"))
                if start < 0 or start > count + 1:
                    raise ValueError("Forming delta starts outside plot history")
                values = change.get("values", [])
                if not isinstance(values, list) or start + len(values) > count + 1:
                    raise ValueError("Forming delta extends outside plot history")
                for offset, value in enumerate(values):
                    wanted = expected(case, start + offset, replacement)
                    if wanted is None:
                        if value is not None:
                            raise ValueError("Public delta NA differs")
                    elif isinstance(value, bool) or not isinstance(value, (int, float)) or struct.pack("!d", float(value)) != struct.pack("!d", wanted):
                        raise ValueError("Public delta IEEE value differs")
                    checked += 1
            item["pythonOracle"] = {"revision": document["revision"], "visibility": "preview",
                                    "seriesValuesChecked": checked, "allDeltaValuesMatchIndependentOracle": True}
        result[name] = item
    return result


def compare_profiles(before, after, case):
    differences = {}
    for name in PROFILE_FIELDS:
        changed = sorted(key for key in before[name] if before[name][key] != after[name][key])
        if set(changed) - {DIFF_PROFILE}:
            raise ValueError("Unexpected complete public profile difference: " + repr(changed))
        if case["case"] == "none" and changed:
            raise ValueError("No-valuewhen control profile differs")
        differences[name] = {key: {"before": before[name][key], "after": after[name][key]} for key in changed}
    return differences


def summary(cases, records):
    result = {}
    for case in cases:
        by_tag = {tag: [row for row in records if row["case"] == case["name"] and row["tag"] == tag]
                  for tag in ("before", "after")}
        if any(len(rows) != REPETITIONS for rows in by_tag.values()):
            raise ValueError("Incomplete fresh-process repetitions")
        for tag, rows in by_tag.items():
            for profile in PROFILE_FIELDS:
                if any(row["metrics"][profile] != rows[0]["metrics"][profile] for row in rows):
                    raise ValueError("Profile differs within same-version repetitions: " + tag)
        differences = compare_profiles(by_tag["before"][0]["metrics"], by_tag["after"][0]["metrics"], case)
        stages = {}
        for name in sorted(SINGLE_STAGES | REPEATED_STAGES):
            fields = {}
            for field in sorted(METRIC_FIELDS):
                samples = {tag: [statistics.median([item[field] for item in row["metrics"]["stages"][name]])
                                 if name in REPEATED_STAGES else row["metrics"]["stages"][name][field]
                                 for row in rows] for tag, rows in by_tag.items()}
                bm, am = statistics.median(samples["before"]), statistics.median(samples["after"])
                fields[field] = {"beforeSamples": samples["before"], "afterSamples": samples["after"],
                    "beforeMedian": bm, "afterMedian": am,
                    "beforeMin": min(samples["before"]), "beforeMax": max(samples["before"]),
                    "afterMin": min(samples["after"]), "afterMax": max(samples["after"]),
                    "afterBeforeRatio": am / bm if bm else None,
                    "unit": "ms" if field == "ms" else "count" if field == "allocations" else "bytes"}
            stages[name] = fields
        result[case["name"]] = {"case": case["case"], "bars": case["bars"], "stages": stages,
            "beforePublicProfiles": {name: by_tag["before"][0]["metrics"][name] for name in PROFILE_FIELDS},
            "afterPublicProfiles": {name: by_tag["after"][0]["metrics"][name] for name in PROFILE_FIELDS},
            "profileDifferences": differences, "onlyAllowedProfileFieldDiffers": True,
            "allRawPayloadPairsByteEqual": True}
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--prepare-only", action="store_true")
    mode.add_argument("--execute", action="store_true")
    parser.add_argument("--timeout", type=float, default=300)
    args = parser.parse_args()
    capacity.numeric(args.timeout, positive=True)
    prepared = prepare()
    if args.prepare_only:
        print("Prepared 9 valuewhen cases / 54 processes; no builds or probes executed.")
        return
    initial = prerequisites(prepared)
    runner_path, plan_path = Path(__file__), D / "valuewhen-plan.json"
    runner_sha, plan_sha = sha(runner_path), sha(plan_path)
    helpers = {name: sha(D / name) for name in ("evidence_common.py", "capacity_runner.py")}
    out = directory("valuewhen")
    receipt = {
        "status": "running", "startedUtc": datetime.now(timezone.utc).isoformat(),
        "plannedProcesses": prepared["plannedProcesses"], "completedProcesses": 0,
        "method": prepared["method"], "prerequisites": initial,
        "runnerSha256": runner_sha, "helperHashes": helpers,
        "plan": {"path": str(plan_path), "sha256": plan_sha},
        "profileSchema": prepared["profileSchema"], "cases": prepared["cases"], "records": [],
        "limits": [
            "Allocation counters measure cumulative requested bytes, count, additional live peak and final live delta within each named public call; they do not measure process RSS.",
            "Repeated public clone/forming samples are individually preserved; summaries use each process's sample median before taking three fresh-process medians.",
            "Clone timings include all HistoricalRuntime state; no-valuewhen and fixed-history controls bound attribution rather than isolating a valuewhen-only timer.",
            "Returned runtime/delta disposal, public profiling, correctness checks, encoders and raw writes occur outside named measurements.",
            "Seed/append measurements retain write-path costs; strategy fixtures have bounded 5k/20k histories to limit the baseline quadratic checkpoint workload.",
            "Three process medians are descriptive rather than confidence intervals, full resource matrices or release-wide performance qualification.",
        ],
    }
    save(out / "progress.json", receipt)
    try:
        for repetition in range(REPETITIONS):
            for case in prepared["cases"]:
                pair = {}
                tags = ("before", "after") if repetition % 2 == 0 else ("after", "before")
                for tag in tags:
                    capacity.no_other_measurements()
                    stem = f'{case["name"]}-{tag}-{repetition}'
                    metrics_file = out / (stem + ".metrics.json")
                    command = [initial["identities"][tag]["binary"], case["case"], str(case["bars"]), str(metrics_file)]
                    run, raw = execute(out, stem, command, args.timeout)
                    row = {"case": case["name"], "tag": tag, "repetition": repetition, "run": run}
                    receipt["records"].append(row)
                    receipt["completedProcesses"] = sum(row["run"]["returncode"] == 0 for row in receipt["records"])
                    save(out / "progress.json", receipt)
                    if run["returncode"] != 0:
                        raise RuntimeError("Valuewhen process failed: " + stem)
                    if Path(run["stderr"]).read_bytes():
                        raise ValueError("Unexpected valuewhen stderr: " + stem)
                    if metrics_file.read_bytes() != raw.rstrip(b"\r\n"):
                        raise ValueError("Metrics file differs from raw stdout")
                    row["metrics"], row["pythonOracles"] = parse_metrics(raw, case, prepared["profileSchema"])
                    row["rawMetrics"] = {"path": str(metrics_file), "sha256": sha(metrics_file), "bytes": metrics_file.stat().st_size}
                    row["rawPayloads"] = raw_payloads(row["metrics"], metrics_file, case)
                    pair[tag] = row
                    save(out / "progress.json", receipt)
                    print(stem, "formingWithoutOutputMsMedian",
                          statistics.median(item["ms"] for item in row["metrics"]["stages"]["formingWithoutOutput"]), flush=True)
                differences = compare_profiles(pair["before"]["metrics"], pair["after"]["metrics"], case)
                for name in pair["before"]["rawPayloads"]:
                    bp = Path(pair["before"]["rawPayloads"][name]["path"])
                    ap = Path(pair["after"]["rawPayloads"][name]["path"])
                    if bp.read_bytes() != ap.read_bytes():
                        raise ValueError("Before/after raw public payload differs: " + name)
                pair["after"]["beforeComparison"] = {"allRawPublicPayloadBytesEqual": True,
                    "profileDifferences": differences, "onlyAllowedProfileFieldDiffers": True,
                    "beforeStdoutSha256": pair["before"]["run"]["stdoutSha256"],
                    "afterStdoutSha256": pair["after"]["run"]["stdoutSha256"]}
                save(out / "progress.json", receipt)
        if prerequisites(prepared) != initial:
            raise ValueError("Final frozen source/gates/links/libraries/quiescence differ")
        if sha(runner_path) != runner_sha or sha(plan_path) != plan_sha:
            raise ValueError("Runner or plan changed during measurement")
        for name, expected_sha in helpers.items():
            if sha(D / name) != expected_sha:
                raise ValueError("Shared receipt helper changed during measurement")
        for row in receipt["records"]:
            for name in ("stdout", "stderr", "exit"):
                if sha(Path(row["run"][name])) != row["run"][name + "Sha256"]:
                    raise ValueError("Raw subprocess artifact changed")
            if sha(Path(row["rawMetrics"]["path"])) != row["rawMetrics"]["sha256"]:
                raise ValueError("Raw metrics artifact changed")
            for payload in row["rawPayloads"].values():
                if sha(Path(payload["path"])) != payload["sha256"]:
                    raise ValueError("Raw public payload artifact changed")
        processes = prepared["plannedProcesses"]
        measures = len(SINGLE_STAGES) + len(REPEATED_STAGES) * SAMPLES
        receipt.update(status="passed", finishedUtc=datetime.now(timezone.utc).isoformat(),
            completedProcesses=processes, rawStageMeasurements=processes * measures,
            rawStageMetricValues=processes * measures * len(METRIC_FIELDS),
            rawRepeatedStageMeasurements=processes * len(REPEATED_STAGES) * SAMPLES,
            pairedStageMetricMedians=len(prepared["cases"]) * (len(SINGLE_STAGES) + len(REPEATED_STAGES)) * len(METRIC_FIELDS),
            rawPublicPayloadFiles=processes * (SAMPLES + 3),
            pairedRawPublicPayloadComparisons=len(prepared["cases"]) * REPETITIONS * (SAMPLES + 3),
            fullProfileComparisons=len(prepared["cases"]) * REPETITIONS * len(PROFILE_FIELDS),
            formingOracleObservations=processes * SAMPLES * 2,
            summary=summary(prepared["cases"], receipt["records"]))
        save(out / "summary.json", receipt)
        save(D / "valuewhen-results.json", receipt)
        print(f"PASS {len(prepared['cases'])} cases / {processes} fresh processes / {processes * measures} stage measurements", flush=True)
    except BaseException as error:
        receipt.update(status="failed", error=repr(error), attemptedProcesses=len(receipt["records"]))
        save(out / "failure.json", receipt)
        save(out / "progress.json", receipt)
        raise


if __name__ == "__main__":
    main()

