"""Small receipt primitives. Importing this module starts no build or probe."""
from __future__ import annotations
from datetime import datetime, timezone
import hashlib
import json
import math
from pathlib import Path
import subprocess
import time
import uuid

D = Path(__file__).resolve().parent
ROOT = D.parents[1]


def sha(path: Path) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def save(path: Path, value: object) -> None:
    path = Path(path)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False),
                   encoding="utf8")
    tmp.replace(path)


def _pairs(items):
    value = {}
    for key, item in items:
        if key in value:
            raise ValueError("Duplicate JSON field: " + key)
        value[key] = item
    return value


def _constant(token):
    raise ValueError("Nonfinite JSON token: " + token)


def _float(token):
    value = float(token)
    if not math.isfinite(value):
        raise ValueError("Out-of-f64-range JSON number: " + token)
    return value


def loads(raw):
    return json.loads(raw, object_pairs_hook=_pairs, parse_constant=_constant,
                      parse_float=_float)


def read(path: Path):
    return loads(Path(path).read_text(encoding="utf-8-sig"))


def source(path: Path, text: str) -> dict:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and path.read_text(encoding="utf8") != text:
        raise ValueError("Frozen generated source differs: " + str(path))
    if not path.exists():
        path.write_bytes(text.encode("utf8"))
    return {"path": str(path), "sha256": sha(path)}


def directory(prefix: str) -> Path:
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ") + "-" + uuid.uuid4().hex[:8]
    out = D / (prefix + "-receipts") / stamp
    out.mkdir(parents=True, exist_ok=False)
    return out


def execute(out: Path, stem: str, command: list[str], timeout: float) -> tuple[dict, bytes]:
    start = time.monotonic()
    try:
        process = subprocess.run(command, cwd=ROOT, capture_output=True, timeout=timeout)
        raw, errors, code = process.stdout, process.stderr, process.returncode
    except subprocess.TimeoutExpired as error:
        raw, errors, code = error.stdout or b"", error.stderr or b"", None
    stdout, stderr, exit_path = (out / (stem + suffix)
                                 for suffix in (".stdout", ".stderr", ".exit.json"))
    stdout.write_bytes(raw)
    stderr.write_bytes(errors)
    row = {"command": command, "returncode": code,
           "wallSeconds": time.monotonic() - start,
           "stdout": str(stdout), "stderr": str(stderr), "exit": str(exit_path),
           "stdoutSha256": sha(stdout), "stderrSha256": sha(stderr)}
    save(exit_path, {"command": command, "returncode": code,
                     "timeoutSeconds": timeout if code is None else None})
    row["exitSha256"] = sha(exit_path)
    return row, raw

