huge = 4294967296 + bar_index % 2
plot(ta.valuewhen(true, close, 4294967296))
plot(ta.valuewhen(true, close, 4294967303))
plot(ta.valuewhen(true, close, huge))
`;
const csv = ['time,open,high,low,close,volume', ...Array.from({length:10}, (_, index) =>
  `${index},${index + 1},${index + 1},${index + 1},${index + 1},1`), ''].join('\n');
const results = [];
for (const version of [5,6]) {
  const wire = pine.runScriptCsv(source.replace('version=6', `version=${version}`), csv);
  fs.writeFileSync(path.join(directory, `wasm-offset-before-v${version}.json`), wire);
  const actual = JSON.parse(wire).plots.map(plot => plot.values);
  const expectedOld = [
    Array.from({length:10}, (_, index) => index + 1),
    Array.from({length:10}, (_, index) => index < 7 ? null : index - 6),
    Array.from({length:10}, (_, index) => 1 + index - index % 2),
  ];
  assert.deepEqual(actual, expectedOld);
  assert.notDeepEqual(actual, Array.from({length:3}, () => Array(10).fill(null)));
  results.push({version, invalidOccurrencesReturnedValues:actual,
    expected:Array.from({length:3}, () => Array(10).fill(null))});
}
const sha = file => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
fs.writeFileSync(path.join(directory, 'wasm-offset-before-receipt.json'), JSON.stringify({
  status:'reproduced', scope:'behavioral repro only, excluded from fresh performance matrix',
  artifactOrigin:'Prior cached debug Wasm and binding generator sealed before this batch compiled any production source; prior gate did not record a Wasm artifact hash, so this is not a new source-to-Wasm build receipt',
  wasmSha256:sha(path.join(directory, 'wasm-before-artifacts/pine_wasm.wasm')),
  bindingGeneratorSha256:sha(path.join(directory, 'wasm-before-artifacts/generate_node_bindings.exe')),
  wrapperSha256:sha(__filename), source, csv, results,
}, null, 2));
process.stdout.write('Reproduced cached Wasm32 occurrence wrap in v5 and v6; excluded from performance matrix\n');

