def require(condition, message):
    if not condition:
        raise ValueError(message)


def resolve(path):
    path = Path(path)
    return path if path.is_absolute() else ROOT / path


def sha(path):
    return hashlib.sha256(resolve(path).read_bytes()).hexdigest()


