    result = {}
    for key, value in pairs:
        require(key not in result, "Duplicate JSON key: " + key)
        result[key] = value
    return result


def reject_constant(token):
    raise ValueError("Nonfinite JSON literal: " + token)


def finite_float(token):
    value = float(token)
    require(math.isfinite(value), "Out-of-f64 JSON value")
    return value


def decode(raw):
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8-sig")
    return json.loads(raw, object_pairs_hook=object_pairs, parse_constant=reject_constant, parse_float=finite_float)


def read(path):
    return decode(resolve(path).read_bytes())


def log_text(path):
    raw = resolve(path).read_bytes()
    return raw.decode("utf16" if raw.startswith((b"\xff\xfe", b"\xfe\xff")) else "utf-8-sig")


def integer(value, nonnegative=True):
    require(type(value) is int, "Expected integer counter")
    if nonnegative:
        require(0 <= value <= 2**64 - 1, "Counter outside usize/u64 range")
    else:
        require(-(2**63) <= value <= 2**63 - 1, "Counter outside i64 range")
    return value


def numeric(value):
    require(type(value) in (int, float) and math.isfinite(value) and value >= 0, "Invalid timing")
    return value


def bits(value):
    return "ffffffffffffffff" if value is None else struct.pack(">d", float(value)).hex()


def same_number(left, right):
    if left is None or right is None:
        return left is right
    return type(left) in (int, float) and type(right) in (int, float) and struct.pack(">d", float(left)) == struct.pack(">d", float(right))


def file_receipt(entry):
    path = resolve(entry["path"])
    require(path.is_file() and sha(path) == entry["sha256"], "Artifact SHA mismatch: " + str(path))
    if "bytes" in entry:
        require(integer(entry["bytes"]) == path.stat().st_size, "Artifact byte count mismatch")
    return path


def source_identity():
    before = read(D / "before-source-identity.json")
    after = read(D / "source-identity.json")
    archives = {}
    for tag, manifest in (("before", before), ("after", after)):
        name = "before-source.tar" if tag == "before" else "source.tar"
        with tarfile.open(D / name, "r") as archive:
            members = {entry.name: entry for entry in archive.getmembers() if entry.isfile()}
            require(len(members) == len(manifest["files"]) and set(members) == set(manifest["files"]), "Tar/source membership mismatch")
            for path, digest in manifest["files"].items():
                stream = archive.extractfile(members[path])
                require(stream is not None and hashlib.sha256(stream.read()).hexdigest() == digest, "Tar member SHA mismatch: " + path)
                if tag == "after":
                    require(sha(ROOT / path) == digest, "Current source differs: " + path)
        archives[tag] = {"files": len(members), "sha256": sha(D / name)}
    baseline = read(D / "before-binary-identity.json")
    require(baseline["baseCommit"] == before["base_commit"] == after["base_commit"], "Baseline parent differs")
    require(baseline["beforeManifestSha256"] == sha(D / "before-source-identity.json"), "Before manifest SHA mismatch")
    require(baseline["beforeArchiveSha256"] == archives["before"]["sha256"], "Before tar SHA mismatch")
    prior_path = resolve(baseline["compiledPriorManifest"])
    require(sha(prior_path) == baseline["compiledPriorManifestSha256"], "Prior compile manifest SHA mismatch")
    prior = read(prior_path)
    require(len(prior["files"]) == baseline["compiledPriorFiles"] and all(before["files"].get(path) == digest for path, digest in prior["files"].items()), "Prior compile source is not unchanged baseline subset")
    require(sha(baseline["priorLinkReceipt"]) == baseline["priorLinkReceiptSha256"], "Prior link receipt SHA mismatch")
    archived = {}
    for original, entry in baseline["libraries"].items():
        actual = file_receipt({"path": entry["archive"], "sha256": entry["sha256"]})
        require(actual.resolve().is_relative_to((D / "baseline").resolve()), "Nonarchived baseline dependency")
        require(str(actual.resolve()) not in archived, "Duplicate archived dependency")
        archived[str(actual.resolve())] = entry["sha256"]
    previous = read(baseline["priorLinkReceipt"])
    for path, digest in previous["libraryHashes"].items():
        matches = [entry for original, entry in baseline["libraries"].items() if original.replace("\\", "/") == path.replace("\\", "/")]
        require(len(matches) == 1 and matches[0]["sha256"] == digest, "Prior release link library differs from baseline")
    changed = sorted(path for path in set(before["files"]) | set(after["files"]) if before["files"].get(path) != after["files"].get(path))
    return {"baseCommit": before["base_commit"], "beforeFiles": len(before["files"]), "afterFiles": len(after["files"]),
        "beforeManifestSha256": sha(D / "before-source-identity.json"), "afterManifestSha256": sha(D / "source-identity.json"),
        "archives": archives, "changedFiles": changed, "baselineCompilerArtifacts": len(archived),
        "baselineObjectCountsBySuffix": dict(Counter(Path(path).suffix for path in archived)),
        "priorCompiledFiles": len(prior["files"]), "baselineIdentitySha256": sha(D / "before-binary-identity.json")}, archived


def links(archived):
    result = {}
    for probe in ("capacity", "valuewhen"):
        pair = {}
        for tag in TAGS:
            entry = read(D / f"identity-{probe}-{tag}.json")
            require(entry["tag"] == tag and entry["probe"] == probe, "Link tag/probe mismatch")
            require(entry["executableSha256"] == sha(D / f"{probe}-{tag}.exe"), "Linked executable differs")
            require(entry["sourceSha256"] == sha(D / f"{probe}_probe.rs"), "Probe source differs")
            manifest = D / ("before-source-identity.json" if tag == "before" else "source-identity.json")
            require(entry["sourceManifestSha256"] == sha(manifest), "Link source manifest differs")
            library_names = {Path(path).name for path in entry["libraryHashes"]}
            require(len(library_names) == 4 and {"libpine_runtime.rlib", "libpine_sema.rlib", "libpine_syntax.rlib"} <= library_names and any(name.startswith("libserde_json-") for name in library_names), "Unexpected direct linked libraries")
            for path, digest in entry["libraryHashes"].items():
                require(sha(path) == digest, "Direct library SHA mismatch")
                if tag == "before":
                    require(archived.get(str(resolve(path).resolve())) == digest, "Before link dependency is not archived")
            args = entry["compilerArguments"]
            dependency_dirs = [args[i + 1] for i, item in enumerate(args) if item == "-L"]
            wanted = "dependency=.local/append-capacity-20261004/baseline/deps" if tag == "before" else "dependency=target/release/deps"
            require(dependency_dirs == [wanted], "Unexpected dependency directory or target fallback")
            require(int(log_text(D / f"link-{probe}-{tag}.exit").strip()) == 0, "Final link exit is nonzero")
            require("error[" not in log_text(D / f"link-{probe}-{tag}.log"), "Final link log reports error")
            pair[tag] = {"identitySha256": sha(D / f"identity-{probe}-{tag}.json"), "executableSha256": entry["executableSha256"],
                "sourceSha256": entry["sourceSha256"], "sourceManifestSha256": entry["sourceManifestSha256"],
                "libraryHashes": entry["libraryHashes"], "compilerArguments": args}
        require(pair["before"]["sourceSha256"] == pair["after"]["sourceSha256"], "Before/after probe source differs")
        result[probe] = pair
    return result


def phase_receipts(source):
    binding = {"manifestSha256": source["afterManifestSha256"], "archiveSha256": source["archives"]["after"]["sha256"], "files": source["afterFiles"], "sourceVerified": True}
    result = {}
    for path in sorted(D.glob("phase-*.json")):
        phase = read(path)
        name = phase["phase"]
        require(phase["status"] == "passed" and phase["returncode"] == 0 and phase["before"] == phase["after"] == binding, "Phase/source did not pass: " + name)
        require(phase["wrapperSha256"] == sha(D / "run_phase.py") and phase["wrapperLogSha256"] == sha(D / f"phase-{name}-wrapper.log"), "Phase helper/log SHA differs")
        artifacts = {}
        if name.startswith("gate-"):
            artifacts = {"gateLogSha256": D / f"{name}.log", "gateExitSha256": D / f"{name}.exit"}
            require(int(log_text(artifacts["gateExitSha256"]).strip()) == 0, "Gate exit differs")
        elif name == "release":
            artifacts = {"buildLogSha256": D / "build-release.log", "buildExitSha256": D / "build-release.exit"}
            require(int(log_text(artifacts["buildExitSha256"]).strip()) == 0, "Build exit differs")
        elif name.startswith("link-"):
            _, probe, tag = name.split("-")
            artifacts = {"linkReceiptSha256": D / f"identity-{probe}-{tag}.json", "linkLogSha256": D / f"link-{probe}-{tag}.log"}
        for key, artifact in artifacts.items():
            require(phase[key] == sha(artifact), "Phase artifact SHA differs: " + name)
        result[name] = {"sha256": sha(path), "artifacts": {key: sha(value) for key, value in artifacts.items()}, "command": phase["command"]}
    require({"gate-windows", "gate-linux", "release", "link-capacity-after", "link-valuewhen-after"} <= set(result), "Required phase receipt missing")
    return result


def gate_results():
    result = {}
    meaningful = ("dynamic_occurrences_keep_event_order_and_bits_across_invalid_reads", "offsets_larger_than_wasm_usize_never_wrap_into_valid_occurrences",
        "repeated_forming_conditions_rollback_then_confirmation_commits_one_event", "repeated_calls_on_one_bar_preserve_each_true_invocation_in_sequence",
        "actual_order_fill_recalculation_restores_the_prior_event_checkpoint", "valuewhen_retained_collection_events_are_roots_but_expired_leaf_cells_are_not")
    for host in ("windows", "linux"):
        path = D / f"gate-{host}.log"
        text = log_text(path)
        tests = re.findall(r"test result: ok\. (\d+) passed; (\d+) failed;", text)
        require(tests and all(int(failed) == 0 for passed, failed in tests), "Rust gate results missing/failed")
        python = re.findall(r"(\d+) passed in [0-9.]+s", text)
        require(len(python) == 1, "Expected one final wheel Python test result")
        structural = re.findall(r"Structural guardrail passed: checked (\d+) production Rust source files\.", text)
        require(len(structural) == 1 and "wasm Node smoke passed:" in text and "Host parity guard passed:" in text, "Missing canonical gate evidence")
        for name in meaningful:
            require(re.search(r"test [^\n]*" + re.escape(name) + r" \.\.\. ok", text), "Missing meaningful native semantic test: " + name)
        result[host] = {"logSha256": sha(path), "rustPassed": sum(int(passed) for passed, _ in tests), "rustResultBlocks": len(tests),
            "pythonPassed": int(python[0]), "productionRustFiles": int(structural[0]), "semanticTestsVerified": list(meaningful),
            "wasmNodePassed": True, "hostParityPassed": True,
            "scope": "Real native semantic tests include replica replay and actual order-fill state; no claim of actual-fill performance from no-fill probes."}
    return result


def process_raw(row, identity):
    run = row["run"]
    require(run["returncode"] == 0, "Failed process qualified")
    numeric(run["wallSeconds"])
    for suffix in ("stdout", "stderr", "exit"):
        require(sha(run[suffix]) == run[suffix + "Sha256"], "Raw subprocess SHA differs")
    require(not resolve(run["stderr"]).read_bytes(), "Unexpected process stderr")
    exit_document = read(run["exit"])
    require(exit_document["returncode"] == 0 and exit_document["timeoutSeconds"] is None and exit_document["command"] == run["command"], "Raw exit command/code differs")
    require(Path(run["command"][0]).resolve() == (D / f'{identity["probe"]}-{row["tag"]}.exe').resolve(), "Process executed wrong binary")
    raw = resolve(run["stdout"]).read_bytes()
    require(len(raw.splitlines()) == 1, "Expected one raw metrics line")
    metrics_path = file_receipt(row["rawMetrics"])
    require(metrics_path.read_bytes() == raw.rstrip(b"\r\n"), "Metrics file and stdout differ")
    metrics = decode(raw)
    require(metrics == row["metrics"], "Producer parsed metrics differ from raw JSON")
    return metrics, metrics_path


def schema_fields():
    text = (ROOT / "crates/pine-runtime/src/output/json/profile.rs").read_text(encoding="utf8")
    fields = re.findall(r'\\"([A-Za-z][A-Za-z0-9]*)\\":', text)
    require(len(fields) == len(set(fields)) >= 100, "Unexpected profile field source")
    return sorted(fields)


def profile_valid(profile, fields):
    require(type(profile) is dict and sorted(profile) == fields, "Public profile schema differs")
    for key, value in profile.items():
        if key == "historyRetentionMode":
            require(value in {"staticTrimmed", "dynamicFull", "maxBarsBack"}, "Bad retention mode")
        elif key == "historyHasDynamicOffsets":
            require(type(value) is bool, "Bad dynamic history flag")
        elif key in {"historyMaxBarsBack", "historyDynamicRetentionMaxMissedOffset"} and value is None:
            continue
        else:
            integer(value)


def all_runs(dataset, cases, link_set):
    require(dataset["status"] == "passed" and dataset["plannedProcesses"] == dataset["completedProcesses"] == len(cases) * 6, "Incomplete fresh processes")
    rows = {}
    for row in dataset["records"]:
        key = (row["case"], row["tag"], row["repetition"])
        require(key not in rows and key[0] in cases and key[1] in TAGS and type(key[2]) is int and 0 <= key[2] < 3, "Duplicate/unplanned process")
        rows[key] = row
    require(len(rows) == len(cases) * 6, "Missing process records")
    expected_order = [(name, tag, rep) for rep in range(3) for name in cases for tag in (TAGS if rep % 2 == 0 else tuple(reversed(TAGS)))]
    require(list(rows) == expected_order, "Paired alternation/sequential record order differs")
    plan_path = file_receipt(dataset["plan"])
    plan = read(plan_path)
    require([case["name"] for case in plan["cases"]] == list(cases) and plan["plannedProcesses"] == len(cases) * 6, "Prepared plan cases differ")
    for case in plan["cases"]:
        source_file = file_receipt(case["source"])
        if "pineSource" in case:
            require(source_file.read_text(encoding="utf8") == case["pineSource"], "Prepared valuewhen Pine source text differs")
    prefix = "capacity" if "sma14" in cases else "valuewhen"
    require(dataset["runnerSha256"] == sha(D / f"{prefix}_runner.py"), "Producer runner changed")
    for helper, expected in dataset["helperHashes"].items():
        require(sha(D / helper) == expected, "Producer helper changed: " + helper)
    binding = dataset["prerequisites"]["sourceBinding"]
    require(binding == {"manifestSha256": sha(D / "source-identity.json"), "archiveSha256": sha(D / "source.tar"),
        "files": len(read(D / "source-identity.json")["files"]), "sourceVerified": True}, "Dataset source binding differs")
    for name, receipt in dataset["prerequisites"]["phases"].items():
        require(sha(receipt["path"]) == receipt["sha256"], "Dataset validation phase identity changed")
    for tag in TAGS:
        expected = dataset["prerequisites"]["identities"][tag]
        require(expected["binarySha256"] == link_set[tag]["executableSha256"] and expected["sourceSha256"] == link_set[tag]["sourceSha256"]
            and expected["sourceManifestSha256"] == link_set[tag]["sourceManifestSha256"] and sha(expected["linkReceipt"]) == expected["linkReceiptSha256"]
            and read(expected["linkReceipt"]) == expected["link"], "Dataset exact link binding differs")
    return rows


def median_record(before, after, field):
    bm, am = statistics.median(before), statistics.median(after)
    return {"beforeSamples": before, "afterSamples": after, "beforeMedian": bm, "afterMedian": am,
        "beforeMin": min(before), "beforeMax": max(before), "afterMin": min(after), "afterMax": max(after),
        "afterBeforeRatio": am / bm if bm else None,
        "unit": "ms" if field.endswith("Ms") or field == "ms" else "ns/call" if field == "profileMedianPerCallNs" else "count" if field == "allocations" else "bytes"}


def check_summary(actual, computed):
    require(set(actual) == set(computed), "Median summary field membership differs")
    for field, expected in computed.items():
        if type(expected) is float:
            require(type(actual[field]) in (int, float) and struct.pack(">d", float(actual[field])) == struct.pack(">d", expected), "Median summary floating value differs: " + field)
        else:
            require(actual[field] == expected, "Median summary differs: " + field)


