                "oracleBits": bits(event_value(kind, count, (count, price))), "previewEvents": retained_events(kind, count + 1),
                "confirmedEvents": retained_events(kind, count), "revision": index + 2}
            require(observation == expected and all(type(observation[field]) is type(value) for field, value in expected.items()), "Forming event/bit/revision observation differs")
        payloads = row["rawPayloads"]
        require(set(payloads) == {"seed", "confirmed", "next-historical"} | {f"forming-apply-{sample}" for sample in range(9)}, "Missing raw public payload")
        expected_paths = [str(metrics_path.with_suffix("." + name + ".json")) for name in ["seed", *[f"forming-apply-{i}" for i in range(9)], "confirmed", "next-historical"]]
        require(metrics["rawPayloadFiles"] == expected_paths, "Original raw payload list differs")
        plot_id = None
        for stage in ("seed", "confirmed", "next-historical"):
            payload = file_receipt(payloads[stage])
            document = read(payload)
            require(len(document["plots"]) == 1, "Wrong public plot count")
            plot = document["plots"][0]
            if plot_id is None:
                plot_id = integer(plot["id"])
            require(plot["id"] == plot_id, "Public plot identity changes")
            actual, expected = plot["values"], proofs[key[0]][stage][0]
            require(len(actual) == len(expected), "Public plot value count differs")
            for index, (observed, wanted) in enumerate(zip(actual, expected)):
                require(same_number(observed, wanted), f"Public plot bit oracle differs at {stage} {index}")
            plot_comparisons += len(expected)
            payload_count += 1
        # Validate value-series delta operations against an independently derived
        # final without-output preview, then all nine real apply-update deltas.
        current = [*proofs[key[0]]["seed"][0], event_value(kind, count, (count, 100.0 + count / 4.0 + 9 / 8.0))]
        for sample in range(9):
            payload = file_receipt(payloads[f"forming-apply-{sample}"])
            document = read(payload)
            require(document["schemaVersion"] == 4 and document["revision"] == 11 + sample and document["baseRevision"] == 10 + sample and document["visibility"] == "preview", "Forming delta version/base/revision differs")
            price = 100.0 + count / 4.0 - (sample + 1) / 8.0
            for change in document["series"]:
                require(change["family"] == "plot" and change["id"] == plot_id, "Unexpected delta series identity")
                start = integer(change["start"])
                values = change.get("values", [])
                require(change["op"] in {"append", "replaceLast"} and start <= len(current), "Unknown/out-of-range delta operation")
                if values:
                    if change["op"] == "append":
                        require(start == len(current), "Append operation does not start at live end")
                        current.extend(values)
                    else:
                        require(start < len(current) and start + len(values) == len(current), "Replacement does not reach live tail")
                        current[start:] = values
                    forming_delta_values += len(values)
            require(len(current) == count + 1 and same_number(current[-1], event_value(kind, count, (count, price))), "Delta replay loses forming tail/length")
            require(all(same_number(observed, wanted) for observed, wanted in zip(current[:-1], proofs[key[0]]["seed"][0])), "Delta changes closed-history values")
            payload_count += 1
        parsed[key] = metrics
    for name in VALUE_CASES:
        summaries[name] = {}
        for profile_name in ("seedProfile", "confirmedProfile", "finalProfile"):
            for tag in TAGS:
                require(all(parsed[(name, tag, rep)][profile_name] == parsed[(name, tag, 0)][profile_name] for rep in range(3)), "Same-version profiles differ across repetitions")
            before, after = parsed[(name, "before", 0)][profile_name], parsed[(name, "after", 0)][profile_name]
            different = {field for field in fields if before[field] != after[field]}
            require(different <= {"valuewhenStateValueCapacity"} and (VALUE_CASES[name][0] != "none" or not different), "Unexpected before/after public profile difference")
            summary = data["summary"][name]
            expected_differences = {field: {"before": before[field], "after": after[field]} for field in different}
            require(summary["beforePublicProfiles"][profile_name] == before and summary["afterPublicProfiles"][profile_name] == after
                and summary["profileDifferences"][profile_name] == expected_differences and summary["onlyAllowedProfileFieldDiffers"] is True,
