                computed = median_record(samples["before"], samples["after"], field)
                check_summary(data["summary"][name]["stages"][stage][field], computed)
                summaries[name][stage][field] = computed
                if computed["afterMedian"] > computed["beforeMedian"] and (computed["beforeMedian"] == 0 or computed["afterBeforeRatio"] > 1.05):
                    increases.append({"case": name, "stage": stage, "field": field, **computed})
    require(data["rawStageMeasurements"] == 2214 and data["rawStageMetricValues"] == 11070 and data["pairedStageMetricMedians"] == 405 and data["rawPublicPayloadFiles"] == 648 and data["pairedRawPublicPayloadComparisons"] == 324, "Valuewhen qualification totals differ")
