            require("error[" not in log_text(D / f"link-{probe}-{tag}.log"), "Final link log reports error")
            pair[tag] = {"identitySha256": sha(D / f"identity-{probe}-{tag}.json"), "executableSha256": entry["executableSha256"],
                "sourceSha256": entry["sourceSha256"], "sourceManifestSha256": entry["sourceManifestSha256"],
                "libraryHashes": entry["libraryHashes"], "compilerArguments": args}
        require(pair["before"]["sourceSha256"] == pair["after"]["sourceSha256"], "Before/after probe source differs")
        result[probe] = pair
    return result


def phase_receipts(source):
    binding = {"manifestSha256": source["afterManifestSha256"], "archiveSha256": source["archives"]["after"]["sha256"], "files": source["afterFiles"], "sourceVerified": True}
    result = {}
    for path in sorted(D.glob("phase-*.json")):
        phase = read(path)
        name = phase["phase"]
        require(phase["status"] == "passed" and phase["returncode"] == 0 and phase["before"] == phase["after"] == binding, "Phase/source did not pass: " + name)
        require(phase["wrapperSha256"] == sha(D / "run_phase.py") and phase["wrapperLogSha256"] == sha(D / f"phase-{name}-wrapper.log"), "Phase helper/log SHA differs")
        artifacts = {}
        if name.startswith("gate-"):
            artifacts = {"gateLogSha256": D / f"{name}.log", "gateExitSha256": D / f"{name}.exit"}
            require(int(log_text(artifacts["gateExitSha256"]).strip()) == 0, "Gate exit differs")
        elif name == "release":
            artifacts = {"buildLogSha256": D / "build-release.log", "buildExitSha256": D / "build-release.exit"}
            require(int(log_text(artifacts["buildExitSha256"]).strip()) == 0, "Build exit differs")
        elif name.startswith("link-"):
            _, probe, tag = name.split("-")
            artifacts = {"linkReceiptSha256": D / f"identity-{probe}-{tag}.json", "linkLogSha256": D / f"link-{probe}-{tag}.log"}
        for key, artifact in artifacts.items():
            require(phase[key] == sha(artifact), "Phase artifact SHA differs: " + name)
        result[name] = {"sha256": sha(path), "artifacts": {key: sha(value) for key, value in artifacts.items()}, "command": phase["command"]}
    require({"gate-windows", "gate-linux", "release", "link-capacity-after", "link-valuewhen-after"} <= set(result), "Required phase receipt missing")
    return result


def gate_results():
    result = {}
    meaningful = ("dynamic_occurrences_keep_event_order_and_bits_across_invalid_reads", "offsets_larger_than_wasm_usize_never_wrap_into_valid_occurrences",
        "repeated_forming_conditions_rollback_then_confirmation_commits_one_event", "repeated_calls_on_one_bar_preserve_each_true_invocation_in_sequence",
        "actual_order_fill_recalculation_restores_the_prior_event_checkpoint", "valuewhen_retained_collection_events_are_roots_but_expired_leaf_cells_are_not")
    for host in ("windows", "linux"):
        path = D / f"gate-{host}.log"
        text = log_text(path)
        tests = re.findall(r"test result: ok\. (\d+) passed; (\d+) failed;", text)
        require(tests and all(int(failed) == 0 for passed, failed in tests), "Rust gate results missing/failed")
        python = re.findall(r"(\d+) passed in [0-9.]+s", text)
        require(len(python) == 1, "Expected one final wheel Python test result")
        structural = re.findall(r"Structural guardrail passed: checked (\d+) production Rust source files\.", text)
        require(len(structural) == 1 and "wasm Node smoke passed:" in text and "Host parity guard passed:" in text, "Missing canonical gate evidence")
        for name in meaningful:
            require(re.search(r"test [^\n]*" + re.escape(name) + r" \.\.\. ok", text), "Missing meaningful native semantic test: " + name)
        result[host] = {"logSha256": sha(path), "rustPassed": sum(int(passed) for passed, _ in tests), "rustResultBlocks": len(tests),
            "pythonPassed": int(python[0]), "productionRustFiles": int(structural[0]), "semanticTestsVerified": list(meaningful),
            "wasmNodePassed": True, "hostParityPassed": True,
            "scope": "Real native semantic tests include replica replay and actual order-fill state; no claim of actual-fill performance from no-fill probes."}
    return result


def process_raw(row, identity):
    run = row["run"]
    require(run["returncode"] == 0, "Failed process qualified")
    numeric(run["wallSeconds"])
    for suffix in ("stdout", "stderr", "exit"):
        require(sha(run[suffix]) == run[suffix + "Sha256"], "Raw subprocess SHA differs")
    require(not resolve(run["stderr"]).read_bytes(), "Unexpected process stderr")
    exit_document = read(run["exit"])
    require(exit_document["returncode"] == 0 and exit_document["timeoutSeconds"] is None and exit_document["command"] == run["command"], "Raw exit command/code differs")
    require(Path(run["command"][0]).resolve() == (D / f'{identity["probe"]}-{row["tag"]}.exe').resolve(), "Process executed wrong binary")
    raw = resolve(run["stdout"]).read_bytes()
    require(len(raw.splitlines()) == 1, "Expected one raw metrics line")
    metrics_path = file_receipt(row["rawMetrics"])
    require(metrics_path.read_bytes() == raw.rstrip(b"\r\n"), "Metrics file and stdout differ")
    metrics = decode(raw)
    require(metrics == row["metrics"], "Producer parsed metrics differ from raw JSON")
    return metrics, metrics_path


def schema_fields():
    text = (ROOT / "crates/pine-runtime/src/output/json/profile.rs").read_text(encoding="utf8")
    fields = re.findall(r'\\"([A-Za-z][A-Za-z0-9]*)\\":', text)
    require(len(fields) == len(set(fields)) >= 100, "Unexpected profile field source")
    return sorted(fields)


def profile_valid(profile, fields):
    require(type(profile) is dict and sorted(profile) == fields, "Public profile schema differs")
    for key, value in profile.items():
        if key == "historyRetentionMode":
            require(value in {"staticTrimmed", "dynamicFull", "maxBarsBack"}, "Bad retention mode")
        elif key == "historyHasDynamicOffsets":
            require(type(value) is bool, "Bad dynamic history flag")
        elif key in {"historyMaxBarsBack", "historyDynamicRetentionMaxMissedOffset"} and value is None:
            continue
        else:
            integer(value)


def all_runs(dataset, cases, link_set):
    require(dataset["status"] == "passed" and dataset["plannedProcesses"] == dataset["completedProcesses"] == len(cases) * 6, "Incomplete fresh processes")
    rows = {}
    for row in dataset["records"]:
        key = (row["case"], row["tag"], row["repetition"])
        require(key not in rows and key[0] in cases and key[1] in TAGS and type(key[2]) is int and 0 <= key[2] < 3, "Duplicate/unplanned process")
        rows[key] = row
    require(len(rows) == len(cases) * 6, "Missing process records")
    expected_order = [(name, tag, rep) for rep in range(3) for name in cases for tag in (TAGS if rep % 2 == 0 else tuple(reversed(TAGS)))]
    require(list(rows) == expected_order, "Paired alternation/sequential record order differs")
    plan_path = file_receipt(dataset["plan"])
    plan = read(plan_path)
    require([case["name"] for case in plan["cases"]] == list(cases) and plan["plannedProcesses"] == len(cases) * 6, "Prepared plan cases differ")
    for case in plan["cases"]:
        source_file = file_receipt(case["source"])
        if "pineSource" in case:
            require(source_file.read_text(encoding="utf8") == case["pineSource"], "Prepared valuewhen Pine source text differs")
    prefix = "capacity" if "sma14" in cases else "valuewhen"
    require(dataset["runnerSha256"] == sha(D / f"{prefix}_runner.py"), "Producer runner changed")
    for helper, expected in dataset["helperHashes"].items():
        require(sha(D / helper) == expected, "Producer helper changed: " + helper)
    binding = dataset["prerequisites"]["sourceBinding"]
    require(binding == {"manifestSha256": sha(D / "source-identity.json"), "archiveSha256": sha(D / "source.tar"),
        "files": len(read(D / "source-identity.json")["files"]), "sourceVerified": True}, "Dataset source binding differs")
    for name, receipt in dataset["prerequisites"]["phases"].items():
        require(sha(receipt["path"]) == receipt["sha256"], "Dataset validation phase identity changed")
    for tag in TAGS:
        expected = dataset["prerequisites"]["identities"][tag]
        require(expected["binarySha256"] == link_set[tag]["executableSha256"] and expected["sourceSha256"] == link_set[tag]["sourceSha256"]
            and expected["sourceManifestSha256"] == link_set[tag]["sourceManifestSha256"] and sha(expected["linkReceipt"]) == expected["linkReceiptSha256"]
            and read(expected["linkReceipt"]) == expected["link"], "Dataset exact link binding differs")
    return rows


def median_record(before, after, field):
    bm, am = statistics.median(before), statistics.median(after)
    return {"beforeSamples": before, "afterSamples": after, "beforeMedian": bm, "afterMedian": am,
        "beforeMin": min(before), "beforeMax": max(before), "afterMin": min(after), "afterMax": max(after),
        "afterBeforeRatio": am / bm if bm else None,
        "unit": "ms" if field.endswith("Ms") or field == "ms" else "ns/call" if field == "profileMedianPerCallNs" else "count" if field == "allocations" else "bytes"}


def check_summary(actual, computed):
    require(set(actual) == set(computed), "Median summary field membership differs")
    for field, expected in computed.items():
        if type(expected) is float:
            require(type(actual[field]) in (int, float) and struct.pack(">d", float(actual[field])) == struct.pack(">d", expected), "Median summary floating value differs: " + field)
        else:
            require(actual[field] == expected, "Median summary differs: " + field)


def capacity_audit(link_set, fields):
    path = D / "capacity-results.json"
    data = read(path)
    rows = all_runs(data, CAPACITY_CASES, link_set)
    parsed, summaries, increases = {}, {}, []
    oracle_values = 0
    for key, row in rows.items():
        kind, count, window, plots = CAPACITY_CASES[key[0]]
        metrics, metrics_path = process_raw(row, {"probe": "capacity"})
        require(metrics["probe"] == "publicProfileAppendCapacity" and (metrics["kind"], metrics["bars"], metrics["window"]) == (kind, count, window), "Capacity fixture differs")
        require(row["run"]["command"][1:] == [row["source"]["path"], kind, str(count), str(window), str(metrics_path)], "Capacity raw command differs")
        file_receipt(row["source"])
        require(metrics["source"] == row["source"]["path"] and metrics["profileUnchanged"] is True, "Capacity source or read-only flag differs")
        groups = metrics["groupMs"]
        require(len(groups) == 31 and metrics["groups"] == 31 and metrics["callsPerGroup"] == 256 and metrics["timedCalls"] == 7936 and metrics["warmupCalls"] == 64, "Wrong profile timing dimensions")
        for value in groups:
            require(numeric(value) > 0, "Zero raw profile timing group")
        computed = statistics.median(groups) * 1000000.0 / 256
        require(same_number(computed, metrics["profileMedianPerCallNs"]), "Raw group median differs")
        for field in CONTROL_TIMES:
            numeric(metrics[field])
        profile_valid(metrics["profile"], fields)
        require(metrics["profileFieldCount"] == len(fields) and metrics["profile"]["bars"] == count and metrics["profile"]["plots"] == plots and metrics["profile"]["plotValues"] == plots * count, "Profile fixture counters differ")
        ticks = sum(400 + index % 17 for index in range(count - window, count)) if kind == "sma" else None
        last_close = (400 + (count - 1) % 17) / 4.0 if count else 0.0
        tails = [(ticks / 4.0) / window] if kind == "sma" else {"empty": [], "constant": [71.25], "close": [last_close], "multiClose": [last_close, 2 * last_close, last_close + 1, -last_close]}[kind]
        wanted_bits = [bits(value) for value in tails]
        require(metrics["plotTailBits"] == metrics["oracleTailBits"] == wanted_bits and metrics["plotValues"] == [count] * plots, "Capacity independent tail oracle differs")
        require(metrics["oracleIntegerQuarterTicks"] == ticks and metrics["oracleWindowStart"] == (count - window if kind == "sma" else None) and metrics["oracleWindowEndExclusive"] == (count if kind == "sma" else None), "Capacity integer oracle differs")
        parsed[key] = metrics
        oracle_values += len(tails)
    for name in CAPACITY_CASES:
        metrics = {tag: [parsed[(name, tag, rep)] for rep in range(3)] for tag in TAGS}
        reference = metrics["before"][0]["profile"]
        require(all(item["profile"] == reference for values in metrics.values() for item in values), "Capacity public profiles differ")
        summary = data["summary"][name]
        kind, count, window, plots = CAPACITY_CASES[name]
        require((summary["kind"], summary["bars"], summary["window"], summary["plots"]) == (kind, count, window, plots)
            and summary["fullProfile"] == reference and summary["profileFieldCount"] == len(fields)
            and summary["beforeAfterAllProfileFieldsEqual"] is True, "Capacity full-profile summary differs")
        require(summary["profileGroupMs"] == {tag: [item["groupMs"] for item in values] for tag, values in metrics.items()}, "Capacity raw group summary differs")
        summaries[name] = {}
        for field in CONTROL_TIMES:
            computed = median_record([item[field] for item in metrics["before"]], [item[field] for item in metrics["after"]], field)
            check_summary(data["summary"][name]["timings"][field], computed)
            summaries[name][field] = computed
            if computed["afterBeforeRatio"] is not None and computed["afterBeforeRatio"] > 1.05:
                increases.append({"case": name, "field": field, **computed})
    require(data["rawTimingValues"] == 216 and data["rawProfileGroupTimingValues"] == 1674 and data["timedProfileCalls"] == 428544, "Capacity accounting totals differ")
    return {"resultsSha256": sha(path), "processes": len(rows), "rawTimingValues": 216, "rawGroups": 1674, "timedProfileCalls": 428544,
        "allProfileFields": len(fields), "profileComparisonsAcrossPairs": 27, "directTailBitComparisons": oracle_values,
        "pairedMedians": summaries, "timingIncreasesOverFivePercent": increases,
        "zeroOuterWallTimeReceipts": [{"case": key[0], "tag": key[1], "repetition": key[2], "wallSeconds": row["run"]["wallSeconds"],
            "stdoutSha256": row["run"]["stdoutSha256"]} for key, row in rows.items() if row["run"]["wallSeconds"] == 0]}


def event_index(kind, index):
    if kind in ("none", "fixed0"):
        return index
    if kind == "fixed1":
        return index - 1
    if kind in ("dynamic", "strategy"):
        return index // 5000 * 5000
    # Build the qualifying-event index, independently of history storage.
    events_seen = index // 257 + 1
    selected_event = events_seen - 1 - index % 17
    return selected_event * 257 if selected_event >= 0 else -1


def event_value(kind, index, replacement=None):
    selected = event_index(kind, index)
    if selected < 0:
        return None
    if replacement is not None and selected == replacement[0]:
        return replacement[1]
    return 100.0 + selected / 4.0


def retained_events(kind, bars):
    if kind == "none":
        return 0
    if kind.startswith("fixed"):
        return min(bars, int(kind[-1]) + 1)
    return min(1000000, (bars + 256) // 257 if kind == "sparse" else bars)


def oracle_array(kind, count, replacement=None):
    values = [event_value(kind, index, replacement) for index in range(count)]
    na = 0
    fnv = 14695981039346656037
    for value in values:
        na += value is None
        raw = b"\xff" * 8 if value is None else struct.pack("<d", value)
        for byte in raw:
            fnv = ((fnv ^ byte) * 1099511628211) % (1 << 64)
    return values, {"plotValues": count, "naValues": na, "allValuesMatchDirectOracle": True, "fnv1a64ValueBitsLe": f"{fnv:016x}"}


def value_audit(link_set, fields):
    path = D / "valuewhen-results.json"
    data = read(path)
    rows = all_runs(data, VALUE_CASES, link_set)
    parsed, summaries, increases, payload_pairs, signed_live_increases = {}, {}, [], [], []
    payload_count = plot_comparisons = forming_delta_values = 0
    proofs = {}
    for name, (kind, count) in VALUE_CASES.items():
        final_price = 100.0 + count / 4.0 + 0.375
        proofs[name] = {
            "seed": oracle_array(kind, count),
            "confirmed": oracle_array(kind, count + 1, (count, final_price)),
            "next-historical": oracle_array(kind, count + 2, (count, final_price)),
        }
    for key, row in rows.items():
        kind, count = VALUE_CASES[key[0]]
        metrics, metrics_path = process_raw(row, {"probe": "valuewhen"})
        require(metrics["probe"] == "publicValuewhenPersistentHistory" and metrics["case"] == kind and metrics["bars"] == count and metrics["samplesPerRepeatedStage"] == 9, "Valuewhen fixture differs")
        planned_case = next(case for case in data["cases"] if case["name"] == key[0])
        require(metrics["pineSource"] == planned_case["pineSource"], "Raw embedded Pine source differs from prepared fixture")
        require(row["run"]["command"][1:] == [kind, str(count), str(metrics_path)], "Valuewhen raw command differs")
        require(metrics["allowedBeforeAfterProfileDifferences"] == ["valuewhenStateValueCapacity"], "Unexpected allowed profile differences")
        require(metrics["seededRevision"] == 1 and metrics["publicRevision"] == 21, "Public revision total differs")
        stages = metrics["stages"]
        require(set(stages) == set(SINGLES) | set(REPEATS), "Wrong public API stages")
        for name, samples in stages.items():
            original = [samples] if name in SINGLES else samples
            require(len(original) == (1 if name in SINGLES else 9), "Wrong original sample count")
            for sample in original:
                require(type(sample) is dict and set(sample) == set(METRICS), "Wrong allocation/time metric fields")
                numeric(sample["ms"])
                for field in METRICS[1:]:
                    integer(sample[field], nonnegative=field != "liveDeltaBytes")
                require(sample["peakAdditionalLiveBytes"] >= max(sample["liveDeltaBytes"], 0), "Live peak below final live delta")
                require(sample["peakAdditionalLiveBytes"] <= sample["allocatedBytes"], "Additional live peak exceeds cumulative allocator requests")
        for profile_name, bars in (("seedProfile", count), ("confirmedProfile", count + 1), ("finalProfile", count + 2)):
            profile = metrics[profile_name]
            profile_valid(profile, fields)
            require(profile["bars"] == bars and profile["plots"] == 1 and profile["plotValues"] == bars and profile["valuewhenStateValues"] == retained_events(kind, bars) and profile["valuewhenStateSlots"] == int(kind != "none"), "Valuewhen public counters differ")
            require(profile["valuewhenStateValueCapacity"] >= retained_events(kind, bars), "Event slot capacity below live events")
            if kind == "strategy":
                expected_passes = bars + (0 if profile_name == "seedProfile" else 18)
                require(profile["strategyScriptPasses"] == expected_passes and profile["strategyRecalculationPasses"] == 0,
                    "No-fill strategy cumulative telemetry excludes forming passes")
        for field, stage in (("seedOracle", "seed"), ("confirmedOracle", "confirmed"), ("finalOracle", "next-historical")):
            require(metrics[field] == proofs[key[0]][stage][1], "Raw probe full-history FNV oracle differs")
        require(len(metrics["formingChecks"]) == 18, "Missing forming observations")
        for index, observation in enumerate(metrics["formingChecks"]):
            sample = index % 9
            price = 100.0 + count / 4.0 + ((sample + 1) / 8.0 if index < 9 else -(sample + 1) / 8.0)
            expected = {"method": "update_without_output" if index < 9 else "apply_update", "sample": sample,
                "oracleBits": bits(event_value(kind, count, (count, price))), "previewEvents": retained_events(kind, count + 1),
                "confirmedEvents": retained_events(kind, count), "revision": index + 2}
            require(observation == expected and all(type(observation[field]) is type(value) for field, value in expected.items()), "Forming event/bit/revision observation differs")
        payloads = row["rawPayloads"]
        require(set(payloads) == {"seed", "confirmed", "next-historical"} | {f"forming-apply-{sample}" for sample in range(9)}, "Missing raw public payload")
        expected_paths = [str(metrics_path.with_suffix("." + name + ".json")) for name in ["seed", *[f"forming-apply-{i}" for i in range(9)], "confirmed", "next-historical"]]
        require(metrics["rawPayloadFiles"] == expected_paths, "Original raw payload list differs")
        plot_id = None
        for stage in ("seed", "confirmed", "next-historical"):
            payload = file_receipt(payloads[stage])
            document = read(payload)
            require(len(document["plots"]) == 1, "Wrong public plot count")
            plot = document["plots"][0]
            if plot_id is None:
                plot_id = integer(plot["id"])
            require(plot["id"] == plot_id, "Public plot identity changes")
            actual, expected = plot["values"], proofs[key[0]][stage][0]
            require(len(actual) == len(expected), "Public plot value count differs")
            for index, (observed, wanted) in enumerate(zip(actual, expected)):
                require(same_number(observed, wanted), f"Public plot bit oracle differs at {stage} {index}")
            plot_comparisons += len(expected)
            payload_count += 1
        # Validate value-series delta operations against an independently derived
        # final without-output preview, then all nine real apply-update deltas.
        current = [*proofs[key[0]]["seed"][0], event_value(kind, count, (count, 100.0 + count / 4.0 + 9 / 8.0))]
        for sample in range(9):
            payload = file_receipt(payloads[f"forming-apply-{sample}"])
            document = read(payload)
            require(document["schemaVersion"] == 4 and document["revision"] == 11 + sample and document["baseRevision"] == 10 + sample and document["visibility"] == "preview", "Forming delta version/base/revision differs")
            price = 100.0 + count / 4.0 - (sample + 1) / 8.0
            for change in document["series"]:
                require(change["family"] == "plot" and change["id"] == plot_id, "Unexpected delta series identity")
                start = integer(change["start"])
                values = change.get("values", [])
                require(change["op"] in {"append", "replaceLast"} and start <= len(current), "Unknown/out-of-range delta operation")
                if values:
                    if change["op"] == "append":
                        require(start == len(current), "Append operation does not start at live end")
                        current.extend(values)
                    else:
                        require(start < len(current) and start + len(values) == len(current), "Replacement does not reach live tail")
                        current[start:] = values
                    forming_delta_values += len(values)
            require(len(current) == count + 1 and same_number(current[-1], event_value(kind, count, (count, price))), "Delta replay loses forming tail/length")
            require(all(same_number(observed, wanted) for observed, wanted in zip(current[:-1], proofs[key[0]]["seed"][0])), "Delta changes closed-history values")
            payload_count += 1
        parsed[key] = metrics
    for name in VALUE_CASES:
        summaries[name] = {}
        for profile_name in ("seedProfile", "confirmedProfile", "finalProfile"):
            for tag in TAGS:
                require(all(parsed[(name, tag, rep)][profile_name] == parsed[(name, tag, 0)][profile_name] for rep in range(3)), "Same-version profiles differ across repetitions")
            before, after = parsed[(name, "before", 0)][profile_name], parsed[(name, "after", 0)][profile_name]
            different = {field for field in fields if before[field] != after[field]}
            require(different <= {"valuewhenStateValueCapacity"} and (VALUE_CASES[name][0] != "none" or not different), "Unexpected before/after public profile difference")
            summary = data["summary"][name]
            expected_differences = {field: {"before": before[field], "after": after[field]} for field in different}
            require(summary["beforePublicProfiles"][profile_name] == before and summary["afterPublicProfiles"][profile_name] == after
                and summary["profileDifferences"][profile_name] == expected_differences and summary["onlyAllowedProfileFieldDiffers"] is True,
                "Valuewhen full-profile summary differs")
        for rep in range(3):
            for payload_name in rows[(name, "before", rep)]["rawPayloads"]:
                bp, ap = (file_receipt(rows[(name, tag, rep)]["rawPayloads"][payload_name]) for tag in TAGS)
                require(bp.read_bytes() == ap.read_bytes(), "Raw public payload before/after bytes differ")
                payload_pairs.append({"case": name, "repetition": rep, "payload": payload_name, "sha256": sha(bp)})
        for stage in (*SINGLES, *REPEATS):
            summaries[name][stage] = {}
            for field in METRICS:
                samples = {}
                for tag in TAGS:
                    samples[tag] = [statistics.median([sample[field] for sample in parsed[(name, tag, rep)]["stages"][stage]]) if stage in REPEATS else parsed[(name, tag, rep)]["stages"][stage][field] for rep in range(3)]
                computed = median_record(samples["before"], samples["after"], field)
                check_summary(data["summary"][name]["stages"][stage][field], computed)
                summaries[name][stage][field] = computed
                if field == "liveDeltaBytes" and computed["afterMedian"] > computed["beforeMedian"]:
                    signed_live_increases.append({"case": name, "stage": stage, **computed,
                        "absoluteChangeBytes": computed["afterMedian"] - computed["beforeMedian"],
                        "meaning": "Signed net allocation change within the call; differing entry live sets make this neither absolute retained runtime memory nor process RSS."})
                if computed["afterMedian"] > computed["beforeMedian"] and (computed["beforeMedian"] == 0 or computed["afterBeforeRatio"] > 1.05):
                    increases.append({"case": name, "stage": stage, "field": field, **computed})
    require(data["rawStageMeasurements"] == 2214 and data["rawStageMetricValues"] == 11070 and data["pairedStageMetricMedians"] == 405 and data["rawPublicPayloadFiles"] == 648 and data["pairedRawPublicPayloadComparisons"] == 324, "Valuewhen qualification totals differ")
    return {"resultsSha256": sha(path), "processes": len(rows), "rawMeasurements": 2214, "rawMetricValues": 11070,
        "pairedStageMetricMedians": 405, "rawPublicPayloads": payload_count, "pairedRawPublicPayloads": len(payload_pairs),
        "directFullPlotBitComparisons": plot_comparisons, "formingDeltaValuesChecked": forming_delta_values, "formingObservations": 972,
        "pairedMedians": summaries, "increasesOverFivePercentOrZeroBaseline": increases,
        "signedLiveDeltaIncreases": signed_live_increases, "pairedPayloadIdentities": payload_pairs,
        "replicaBoundary": "This auditor independently applies value-series operations to a formula-derived preview. Full RuntimeReplica/idempotent replay is covered by real native semantic tests and canonical WASM execution, not claimed from the performance probe."}


def exclusions(link_set, source):
    interrupted_dir = D / "superseded-interrupted-links"
    interrupted_path = interrupted_dir / "archive-identity.json"
    interrupted = read(interrupted_path)
    require(interrupted["attemptedLinks"] == 2 and interrupted["completedLinks"] == 0
        and interrupted["qualifiedPerformanceProcesses"] == 0, "Interrupted links incorrectly qualified")
    require(interrupted["sourceManifestSha256"] == source["afterManifestSha256"], "Interrupted source differs")
    for name, digest in interrupted["artifactSha256"].items():
        require(sha(interrupted_dir / name) == digest, "Interrupted link artifact changed: " + name)
    for probe in ("capacity", "valuewhen"):
        phase = read(interrupted_dir / f"phase-link-{probe}-after.json")
        require(phase["status"] == "running" and "returncode" not in phase and "after" not in phase, "Interrupted link claimed completion")
        require(not (interrupted_dir / f"link-{probe}-after.exit").exists()
            and not (interrupted_dir / f"identity-{probe}-after.json").exists()
            and not (interrupted_dir / f"{probe}-after.exe").exists(), "Unexpected interrupted completion artifact")
    freeze_dir = D / "freeze-path-key-failure"
    freeze_error = (freeze_dir / "failure.txt").read_text(encoding="utf8")
    require("KeyError" in freeze_error and "path separators" in freeze_error, "Freeze failure reason differs")
    excluded_dir = D / "valuewhen-receipts/20261005T010641.353301Z-2af843a6"
    excluded_path = excluded_dir / "excluded-guard-identity.json"
    excluded = read(excluded_path)
    require(excluded["status"] == "excluded" and excluded["executedProcesses"] == 15 and excluded["qualifiedProcesses"] == 0,
        "First guard-failed attempt incorrectly qualified")
    require(excluded["failureSha256"] == sha(excluded_dir / "failure.json"), "Guard failure receipt changed")
    for name, entry in excluded["rawArtifacts"].items():
        file_receipt({"path": str(excluded_dir / name), **entry})
    for name, entry in excluded["frozenSources"].items():
        file_receipt({"path": entry["archivePath"], "sha256": entry["sha256"], "bytes": entry["bytes"]})
    require(excluded["oldRunnerSha256"] == sha(excluded_dir / "frozen-sources/valuewhen_runner.py")
        and excluded["oldPlanSha256"] == sha(excluded_dir / "frozen-sources/valuewhen-plan.json"), "Excluded old helper identity differs")
    failure = read(excluded_dir / "failure.json")
    require(failure["status"] == "failed" and len(failure["records"]) == 15 and failure["completedProcesses"] == 15,
        "Excluded guard attempt count/status differs")
    require(failure["runnerSha256"] == excluded["oldRunnerSha256"] and "strategy" in failure["error"].lower(), "Guard failure/helper reason differs")
    require(excluded["sourceBinding"] == failure["prerequisites"]["sourceBinding"]
        and excluded["sourceBinding"]["manifestSha256"] == source["afterManifestSha256"], "Excluded production source differs")
    fresh = read(D / "valuewhen-results.json")
    old_locators = {str(resolve(row["run"]["stdout"]).parent) for row in failure["records"]}
    require(all(str(resolve(row["run"]["stdout"]).parent) not in old_locators for row in fresh["records"]), "Excluded process mixed into new qualification")
    old_payloads = old_bit_checks = 0
    for row in failure["records"]:
        run = row["run"]
        for suffix in ("stdout", "stderr", "exit"):
            require(sha(run[suffix]) == run[suffix + "Sha256"], "Excluded raw receipt changed")
        exit_document = read(run["exit"])
        require(run["returncode"] == exit_document["returncode"] == 0 and not resolve(run["stderr"]).read_bytes(), "Excluded Rust child did not pass")
        require(exit_document["command"] == run["command"] and exit_document["timeoutSeconds"] is None, "Excluded exit invocation differs")
        raw = resolve(run["stdout"]).read_bytes()
        metrics_file = resolve(run["command"][-1])
        require(metrics_file.read_bytes() == raw.rstrip(b"\r\n") and len(raw.splitlines()) == 1, "Excluded stdout and metrics differ")
        metrics = decode(raw)
        kind, count = VALUE_CASES[row["case"]]
        require(metrics["case"] == kind and metrics["bars"] == count and metrics["publicRevision"] == 21, "Excluded fixture differs")
        for profile_name, bars in (("seedProfile", count), ("confirmedProfile", count + 1), ("finalProfile", count + 2)):
            profile = metrics[profile_name]
            require(profile["bars"] == bars and profile["valuewhenStateValues"] == retained_events(kind, bars), "Excluded live event counters differ")
            if kind == "strategy":
                require(profile["strategyScriptPasses"] == bars + (0 if profile_name == "seedProfile" else 18)
                    and profile["strategyRecalculationPasses"] == 0, "Excluded strategy cumulative telemetry differs")
        for stage, measure in metrics["stages"].items():
            samples = [measure] if stage in SINGLES else measure
            require(len(samples) == (1 if stage in SINGLES else 9), "Excluded original stage samples missing")
            for sample in samples:
                require(set(sample) == set(METRICS), "Excluded metric schema differs")
                numeric(sample["ms"])
                for field in METRICS[1:]:
                    integer(sample[field], nonnegative=field != "liveDeltaBytes")
        for stage, suffix, bars in (("seedOracle", "seed", count), ("confirmedOracle", "confirmed", count + 1),
            ("finalOracle", "next-historical", count + 2)):
            replacement = None if suffix == "seed" else (count, 100.0 + count / 4.0 + 0.375)
            wanted, proof = oracle_array(kind, bars, replacement)
            require(metrics[stage] == proof, "Excluded full-history FNV proof differs")
            document = read(metrics_file.with_suffix("." + suffix + ".json"))
            actual = document["plots"][0]["values"]
            require(len(actual) == bars and all(same_number(left, right) for left, right in zip(actual, wanted)), "Excluded raw public snapshot differs")
            old_bit_checks += bars
            old_payloads += 1
        for sample in range(9):
            document = read(metrics_file.with_suffix(f".forming-apply-{sample}.json"))
            require(document["revision"] == 11 + sample and document["baseRevision"] == 10 + sample
                and document["visibility"] == "preview", "Excluded forming delta revision differs")
            replacement = (count, 100.0 + count / 4.0 - (sample + 1) / 8.0)
            for change in document["series"]:
                require(change["family"] == "plot", "Excluded delta family differs")
                for offset, actual in enumerate(change.get("values", [])):
                    require(same_number(actual, event_value(kind, change["start"] + offset, replacement)), "Excluded delta bit oracle differs")
            old_payloads += 1
    require(old_payloads == 180, "Excluded public payload count differs")
    for tag in TAGS:
        require(excluded["probeAndBinaryIdentities"][tag]["binarySha256"] == link_set[tag]["executableSha256"]
            and excluded["probeAndBinaryIdentities"][tag]["sourceSha256"] == link_set[tag]["sourceSha256"], "Excluded source/binary differs from fresh run")
    wasm_path = D / "wasm-offset-before-receipt.json"
    wasm = read(wasm_path)
    require(wasm["status"] == "reproduced" and "excluded" in wasm["scope"] and "not a new source-to-Wasm" in wasm["artifactOrigin"], "Cached Wasm scope qualifier missing")
    require(wasm["wasmSha256"] == sha(D / "wasm-before-artifacts/pine_wasm.wasm")
        and wasm["bindingGeneratorSha256"] == sha(D / "wasm-before-artifacts/generate_node_bindings.exe")
        and wasm["wrapperSha256"] == sha(D / "reproduce_wasm_offset.cjs"), "Cached Wasm behavioral artifact identity differs")
    expected_wrapped = [[index + 1 for index in range(10)], [None] * 7 + [1, 2, 3], [index + 1 - index % 2 for index in range(10)]]
    wasm_raw = {}
    for version in (5, 6):
        raw_path = D / f"wasm-offset-before-v{version}.json"
        document = read(raw_path)
        values = [plot["values"] for plot in document["plots"]]
        require(values == expected_wrapped, "Cached Wasm behavioral wrap no longer reproduced")
        entry = next(item for item in wasm["results"] if item["version"] == version)
        require(entry["invalidOccurrencesReturnedValues"] == values and entry["expected"] == [[None] * 10 for _ in range(3)], "Cached Wasm raw and behavioral receipt differ")
        wasm_raw[str(version)] = {"sha256": sha(raw_path), "returnedValues": values}
    return {
        "interruptedAfterLinks": {"identitySha256": sha(interrupted_path), "attemptedLinks": 2, "completedLinks": 0,
            "qualifiedProcesses": 0, "archivedArtifactsVerified": len(interrupted["artifactSha256"]), "reason": interrupted["cause"]},
        "initialBaselineFreezePathKey": {"helperSha256": sha(freeze_dir / "freeze_baseline.py"), "failureSha256": sha(freeze_dir / "failure.txt"),
            "qualifiedProcesses": 0, "reason": freeze_error.strip()},
        "firstGuardFailedValuewhenAttempt": {"identitySha256": sha(excluded_path), "failureSha256": excluded["failureSha256"],
            "oldRunnerSha256": excluded["oldRunnerSha256"], "oldPlanSha256": excluded["oldPlanSha256"], "executedProcesses": 15,
            "qualifiedProcesses": 0, "allRustExitsZero": True, "rawArtifactsVerified": len(excluded["rawArtifacts"]),
            "rawPublicPayloadsRechecked": old_payloads, "directSnapshotBitChecks": old_bit_checks,
            "reason": excluded["reason"], "freshRunUsesSeparateRawLocators": True},
        "cachedWasmOccurrenceBehaviorOnly": {"identitySha256": sha(wasm_path), "wasmSha256": wasm["wasmSha256"],
            "bindingGeneratorSha256": wasm["bindingGeneratorSha256"], "wrapperSha256": wasm["wrapperSha256"],
            "versions": wasm_raw, "qualifiedPerformanceProcesses": 0, "artifactOrigin": wasm["artifactOrigin"], "scope": wasm["scope"]},
    }


def main(attempt):
    source, archived = source_identity()
    link = links(archived)
    phases = phase_receipts(source)
    gates = gate_results()
    fields = schema_fields()
    capacity = capacity_audit(link["capacity"], fields)
    valuewhen = value_audit(link["valuewhen"], fields)
    excluded = exclusions(link["valuewhen"], source)
    result = {"status": "passed", "finishedUtc": datetime.now(timezone.utc).isoformat(),
        "auditorSha256": sha(Path(__file__)), "method": "stdlib only; no producer imports or subprocesses; independently reparse raw files and derive bit/event/median oracles",
        "attempt": {"path": str(attempt), "sourceSha256": sha(attempt / "audit_append_capacity.py")},
        "independence": "Auditor authored AppendHistory cache; probes, runners, fixture scheduling and data production were authored by other agents.",
        "qualifiedFreshProcesses": capacity["processes"] + valuewhen["processes"], "source": source,
        "attemptedPerformanceProcesses": capacity["processes"] + valuewhen["processes"] + 15,
        "excludedAttempts": excluded,
        "links": link, "phases": phases, "canonicalGates": gates, "capacity": capacity, "valuewhen": valuewhen,
        "measurementLimits": ["Allocator requested bytes/count and additional live peak are not OS RSS or process peak.",
            "peakAdditionalLiveBytes is maximum allocator-request live bytes above stage entry LIVE; earlier deallocations may hide subsequent allocations below that baseline.",
            "Realloc accounting records logical old-layout removal/new-layout addition; it does not observe allocator implementation transient buffers.",
            "Public profile still includes other collection/nested-state walks; only AppendHistory::capacity itself becomes constant time.",
            "Actual order-fill behavior and full replica replay are tested; their performance is not qualified by the no-fill strategy probe.",
            "Three fresh-process medians and nine repeated-call samples are descriptive, not confidence intervals or a full resource matrix."]}
    (D / "audit-results.json").write_text(json.dumps(result, indent=2, ensure_ascii=False, allow_nan=False), encoding="utf8")
    (attempt / "receipt.json").write_text(json.dumps({"status": "passed", "auditResultsSha256": sha(D / "audit-results.json"),
        "auditorSha256": sha(Path(__file__)), "qualifiedFreshProcesses": result["qualifiedFreshProcesses"]}, indent=2), encoding="utf8")
    print("PASS independent audit", result["qualifiedFreshProcesses"], "fresh processes", flush=True)


if __name__ == "__main__":
    attempt = D / "audit-attempts" / datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ")
    attempt.mkdir(parents=True, exist_ok=False)
    (attempt / "audit_append_capacity.py").write_bytes(Path(__file__).read_bytes())
    try:
        main(attempt)
    except BaseException as error:
        (attempt / "receipt.json").write_text(json.dumps({"status": "failed", "auditorSha256": sha(Path(__file__)),
            "error": repr(error), "traceback": traceback.format_exc()}, indent=2, ensure_ascii=False), encoding="utf8")
        raise
